// The K-12 multiple-choice item set — the questions the k12 benchmark is scored on.
//
// Data only. The prompt format, the grader, the statistics and the pre-registered bar live in
// k12-fixture.ts; nothing in this file is executed. Items are SELF-AUTHORED for this benchmark and
// are not comparable to MMLU, NAEP or any published set.
//
// ── Blueprint ────────────────────────────────────────────────────────────────
// Items per cell and the strands inside each cell. This table is the blueprint: it is committed
// BEFORE any item is written, and the items are written to it, never the other way round.
//
// |                        | K-5 (20)                                  | 6-8 (20)                                   | 9-12 (20)                                    |
// |------------------------|-------------------------------------------|--------------------------------------------|----------------------------------------------|
// | Math (all `apply`)     | whole-number arithmetic, place value 6;   | ratio, rate, percent 5;                    | quadratics, systems, exponents 7;            |
// |                        | fractions, decimals 5;                    | integer and rational operations 3;         | linear, exponential, log functions 4;        |
// |                        | measurement, time, money 3;               | expressions, linear equations 5;           | geometry, trigonometry 4;                    |
// |                        | perimeter, area, shapes 3;                | area, volume, angles, Pythagoras 4;        | statistics, probability 3;                   |
// |                        | patterns, data in words 3                 | statistics, probability 3                  | sequences 2                                  |
// | Science                | life 6; earth and space 5;                | cells, heredity, ecosystems 6;             | biology 6; chemistry 6 (3+ computed);        |
// |                        | matter, forces, energy 6;                 | motion, energy, waves 5;                   | physics 6 (4+ computed);                     |
// |                        | measurement and method 3                  | atoms, periodic table, reactions 5;        | earth/environment 2                          |
// |                        |                                           | earth and space 4                          |                                              |
// | ELA                    | parts of speech, grammar 6;               | grammar, sentence structure 6;             | usage and style 5;                           |
// |                        | spelling, punctuation 4; vocabulary 5;    | word roots, vocabulary 4;                  | rhetoric, fallacies 5;                       |
// |                        | comprehension of an original 2-3          | figurative language, literary terms 5;     | literary analysis of an original passage 6;  |
// |                        | sentence passage 5                        | inference on an original passage 5         | vocabulary in context 4                      |
// | Social studies         | civics basics 5;                          | world history to 1450 6;                   | US history 1877-1991 5;                      |
// |                        | geography, map skills 6;                  | US history to 1877 6;                      | world history 1450-1991 5;                   |
// |                        | US history basics 5;                      | Constitution, branches 4;                  | US government 5;                             |
// |                        | economics basics 4                        | geography 4                                | economics 5 (2+ computed)                    |
//
// Bands are the author's judgement of when a topic is typically taught, not alignment to a
// published standard; the write-up says so.
//
// ── Authoring rules ──────────────────────────────────────────────────────────
// Rules that prevent circularity:
//  1. Write without opening `public/library/` or the sibling `openedu-library` repo. Topics come
//     from the blueprint, never from the card list.
//  2. `basis` is a computation or a primary/authoritative fact (constitutional text, a physical
//     constant, a grammar rule). "The card says so" is never a basis.
//  3. Nothing is harvested from `src/lib/steps/` output, datasets, cards, or any released test item.
//     No OpenStax, CK-12, Wikimedia text.
//  4. After authoring, items are not edited in response to what the retriever returns. If a card
//     contains the answer, that is the product working; if it retrieves a wrong card, that is a
//     finding.
//
// Rules that prevent ambiguity:
//  5. Exactly one defensible key. Distractors are specific misconceptions or the result of a named
//     wrong step. No "all/none of the above", no "which is NOT" double negatives.
//  6. No time-sensitive facts (office holders, populations, records, "current"), nothing after 1991
//     in history, no US-state-specific content, no item needing a figure.
//  7. Numeric options share units and precision; the key is not the only option of its form or the
//     longest by a wide margin.
//  8. ELA passages are original sentences written for the item. No quoted copyrighted text.
//  9. Keys are placed to hit exactly 5 per letter per cell.
//
// Ids: "math-k5-07", "science-68-12", "ela-912-03", "social-k5-20" — subject, band, two-digit
// sequence within the cell. Pilot ids are "pilot-01".."pilot-12", one per cell.
//
// One object per line. k12-fixture.test.ts enforces the counts, the key balance and the id scheme.

export type K12Subject = "math" | "science" | "ela" | "social-studies";
export type K12Band = "K-5" | "6-8" | "9-12";
export type K12Key = "A" | "B" | "C" | "D";

export interface K12Item {
  id: string;
  subject: K12Subject;
  band: K12Band;
  /** Descriptive tag, not a stratum. */
  demand: "recall" | "apply";
  /** The blueprint strand this item was written to. Descriptive. */
  strand?: string;
  /** Self-contained; any passage is original text inside the stem. */
  stem: string;
  /** Rendered A-D in this order. */
  options: [string, string, string, string];
  key: K12Key;
  /** Why the key is true: "computed: 3/4 + 1/8 = 7/8" or "US Constitution, Art. I s.3". */
  basis: string;
}

// ── The scored set ───────────────────────────────────────────────────────────
// 240 items, 20 per subject x band cell. NOT sent to the model before the freeze commit.

export const K12_ITEMS: K12Item[] = [
  { id: "math-k5-01", subject: "math", band: "K-5", demand: "apply", strand: "whole-number arithmetic, place value", stem: "What is 407 + 285?", options: ["682", "692", "792", "122"], key: "B", basis: "computed: 7 + 5 = 12 (write 2, carry 1); 0 + 8 + 1 = 9; 4 + 2 = 6; sum = 692. 682 drops the carry, 792 carries into the hundreds wrongly, 122 subtracts." },
  { id: "math-k5-02", subject: "math", band: "K-5", demand: "apply", strand: "whole-number arithmetic, place value", stem: "In the number 58,362, what is the value of the digit 8?", options: ["800", "80,000", "8,000", "8"], key: "C", basis: "computed: 58,362 = 50,000 + 8,000 + 300 + 60 + 2; the 8 is in the thousands place, so its value is 8 x 1,000 = 8,000." },
  { id: "math-k5-03", subject: "math", band: "K-5", demand: "apply", strand: "whole-number arithmetic, place value", stem: "Round 6,748 to the nearest hundred.", options: ["6,700", "6,800", "7,000", "6,750"], key: "A", basis: "computed: 6,748 lies between 6,700 and 6,800; the tens digit is 4 (less than 5), so round down to 6,700. 6,800 rounds up wrongly, 7,000 is nearest thousand, 6,750 is nearest ten." },
  { id: "math-k5-04", subject: "math", band: "K-5", demand: "apply", strand: "whole-number arithmetic, place value", stem: "A library had 3,002 books. It gave away 1,468 books. How many books does the library have left?", options: ["2,466", "1,534", "1,634", "4,470"], key: "B", basis: "computed: 3,002 - 1,468 = 1,534 (check: 1,534 + 1,468 = 3,002). 2,466 subtracts the smaller digit from the larger in each column, 1,634 is a regrouping error in the hundreds, 4,470 adds." },
  { id: "math-k5-05", subject: "math", band: "K-5", demand: "apply", strand: "whole-number arithmetic, place value", stem: "A school has 24 classrooms. Each classroom has 36 desks. How many desks are in the school altogether?", options: ["864", "216", "60", "764"], key: "A", basis: "computed: 24 x 36 = 24 x 30 + 24 x 6 = 720 + 144 = 864. 216 adds the partial products 72 + 144 without the place-value shift, 60 adds the factors, 764 is a carrying error." },
  { id: "math-k5-06", subject: "math", band: "K-5", demand: "apply", strand: "whole-number arithmetic, place value", stem: "A baker made 125 muffins. Each box holds 8 muffins. What is the smallest number of boxes the baker needs so that every muffin is in a box?", options: ["15", "5", "117", "16"], key: "D", basis: "computed: 125 / 8 = 15 remainder 5 (8 x 15 = 120); the 5 leftover muffins need one more box, so 15 + 1 = 16. 15 ignores the remainder, 5 is the remainder, 117 subtracts." },
  { id: "math-k5-07", subject: "math", band: "K-5", demand: "apply", strand: "fractions, decimals", stem: "Which of these fractions is greater than 1/2?", options: ["5/8", "3/8", "2/5", "4/9"], key: "A", basis: "computed: half of 8 is 4, and 5 > 4, so 5/8 > 1/2. 3/8 (3 < 4), 2/5 (2 < 2.5) and 4/9 (4 < 4.5) are all less than 1/2." },
  { id: "math-k5-08", subject: "math", band: "K-5", demand: "apply", strand: "fractions, decimals", stem: "Lena has 24 beads. Exactly 3/8 of her beads are red. How many of her beads are red?", options: ["3 beads", "15 beads", "9 beads", "64 beads"], key: "C", basis: "computed: 24 / 8 = 3 beads in each eighth; 3 x 3 = 9. 3 stops after dividing by 8, 15 is the number that are not red, 64 comes from 24 x 8 / 3." },
  { id: "math-k5-09", subject: "math", band: "K-5", demand: "apply", strand: "fractions, decimals", stem: "Which of these decimals has the greatest value?", options: ["0.602", "0.26", "0.098", "0.62"], key: "D", basis: "computed: writing each to thousandths gives 0.620, 0.602, 0.260, 0.098; 620 thousandths is the largest. 0.602 reflects 'more digits means bigger', 0.26 reverses the digits, 0.098 focuses on the large digits 9 and 8." },
  { id: "math-k5-10", subject: "math", band: "K-5", demand: "apply", strand: "fractions, decimals", stem: "What is 4.5 - 1.75?", options: ["2.75", "3.25", "6.25", "2.85"], key: "A", basis: "computed: 4.50 - 1.75 = 2.75 (check: 2.75 + 1.75 = 4.50). 3.25 subtracts smaller digits from larger in each column, 6.25 adds, 2.85 is a regrouping error in the tenths." },
  { id: "math-k5-11", subject: "math", band: "K-5", demand: "apply", strand: "fractions, decimals", stem: "What is 3/4 + 1/6?", options: ["4/10", "4/12", "3/24", "11/12"], key: "D", basis: "computed: 3/4 = 9/12 and 1/6 = 2/12; 9/12 + 2/12 = 11/12. 4/10 adds numerators and denominators, 4/12 uses the common denominator without changing numerators, 3/24 multiplies the fractions." },
  { id: "math-k5-12", subject: "math", band: "K-5", demand: "apply", strand: "measurement, time, money", stem: "A rope is 4 feet 7 inches long. How long is the rope in inches?", options: ["55 inches", "47 inches", "48 inches", "11 inches"], key: "A", basis: "computed: 1 foot = 12 inches; 4 x 12 = 48; 48 + 7 = 55 inches. 47 treats a foot as 10 inches, 48 forgets the extra 7 inches, 11 adds 4 + 7." },
  { id: "math-k5-13", subject: "math", band: "K-5", demand: "apply", strand: "measurement, time, money", stem: "A movie starts at 2:45 PM and lasts 1 hour 50 minutes. At what time does the movie end?", options: ["3:35 PM", "4:35 PM", "4:25 PM", "12:55 PM"], key: "B", basis: "computed: 2:45 + 1 hour = 3:45; 3:45 + 50 minutes = 4:35 PM. 3:35 forgets the hour gained when minutes pass 60, 4:25 is a minutes error, 12:55 subtracts the duration." },
  { id: "math-k5-14", subject: "math", band: "K-5", demand: "apply", strand: "measurement, time, money", stem: "Marco buys 3 notebooks that cost $1.35 each. He pays with a $5.00 bill. How much change should he get back?", options: ["$3.65", "$0.95", "$4.05", "$1.95"], key: "B", basis: "computed: 3 x $1.35 = $4.05; $5.00 - $4.05 = $0.95. $3.65 subtracts the price of only one notebook, $4.05 is the total cost, $1.95 is a regrouping error." },
  { id: "math-k5-15", subject: "math", band: "K-5", demand: "apply", strand: "perimeter, area, shapes", stem: "A rectangular garden is 9 meters long and 6 meters wide. What is the perimeter of the garden?", options: ["15 meters", "30 meters", "54 meters", "21 meters"], key: "B", basis: "computed: perimeter = 2 x (9 + 6) = 2 x 15 = 30 meters. 15 adds only two sides, 54 is the area number (9 x 6), 21 adds only three sides (9 + 6 + 6)." },
  { id: "math-k5-16", subject: "math", band: "K-5", demand: "apply", strand: "perimeter, area, shapes", stem: "A rectangle has an area of 84 square centimeters. Its width is 7 centimeters. What is its length?", options: ["77 centimeters", "35 centimeters", "588 centimeters", "12 centimeters"], key: "D", basis: "computed: area = length x width, so length = 84 / 7 = 12 centimeters. 77 subtracts 84 - 7, 35 treats 84 as a perimeter (84 / 2 - 7), 588 multiplies 84 x 7." },
  { id: "math-k5-17", subject: "math", band: "K-5", demand: "apply", strand: "perimeter, area, shapes", stem: "Tasha draws a closed shape with 4 straight sides. Exactly one pair of its sides is parallel. What kind of shape did Tasha draw?", options: ["parallelogram", "rhombus", "trapezoid", "pentagon"], key: "C", basis: "Definition: a quadrilateral with exactly one pair of parallel sides is a trapezoid. A parallelogram and a rhombus each have two pairs of parallel sides; a pentagon has 5 sides." },
  { id: "math-k5-18", subject: "math", band: "K-5", demand: "apply", strand: "patterns, data described in words", stem: "A number pattern starts 4, 11, 18, 25 and keeps following the same rule. What is the 7th number in the pattern?", options: ["32", "39", "46", "53"], key: "C", basis: "computed: the rule is add 7; terms are 4, 11, 18, 25, 32, 39, 46, so the 7th is 46 (4 + 6 x 7). 32 is the next (5th) term, 39 is the 6th, 53 adds seven 7s (the 8th term)." },
  { id: "math-k5-19", subject: "math", band: "K-5", demand: "apply", strand: "patterns, data described in words", stem: "A lemonade stand sold 13 cups on Monday, 24 cups on Tuesday, 8 cups on Wednesday, and 19 cups on Thursday. How many more cups were sold on the two best days combined than on the two worst days combined?", options: ["16 cups", "64 cups", "22 cups", "11 cups"], key: "C", basis: "computed: best two days 24 + 19 = 43; worst two days 13 + 8 = 21; 43 - 21 = 22 cups. 16 is highest minus lowest (24 - 8), 64 is the total of all four days, 11 is Tuesday minus Monday." },
  { id: "math-k5-20", subject: "math", band: "K-5", demand: "apply", strand: "patterns, data described in words", stem: "In a picture graph, each book symbol stands for 4 books. Ravi's row shows 6 symbols. Mia's row shows 3 whole symbols and one half symbol. How many more books did Ravi read than Mia?", options: ["12 books", "38 books", "14 books", "10 books"], key: "D", basis: "computed: Ravi 6 x 4 = 24; Mia 3 x 4 + 2 = 14; 24 - 14 = 10 books. 12 ignores the half symbol, 38 is the total for both, 14 is Mia's count only." },
  { id: "math-68-01", subject: "math", band: "6-8", demand: "apply", strand: "ratio, rate, percent", stem: "A bread recipe uses 3 cups of flour for every 2 cups of water. If a baker uses 6 cups of water, how much flour is needed to keep the same ratio?", options: ["4 cups", "7 cups", "9 cups", "18 cups"], key: "C", basis: "computed: flour/water = 3/2, so flour = 6 x 3/2 = 9 cups. Distractors: 4 = inverted ratio (6 x 2/3); 7 = additive reasoning (6 + 1); 18 = 6 x 3 without dividing by 2." },
  { id: "math-68-02", subject: "math", band: "6-8", demand: "apply", strand: "ratio, rate, percent", stem: "A delivery van travels 60 miles in 4 hours at a constant speed. At the same speed, how far will it travel in 6 hours?", options: ["62 miles", "90 miles", "40 miles", "360 miles"], key: "B", basis: "computed: 60 / 4 = 15 miles per hour; 15 x 6 = 90 miles. Distractors: 62 = added the 2 extra hours to 60; 40 = inverted proportion (60 x 4/6); 360 = 60 x 6." },
  { id: "math-68-03", subject: "math", band: "6-8", demand: "apply", strand: "ratio, rate, percent", stem: "A jacket has a regular price of $80. It is on sale for 25% off, and a 5% sales tax is then charged on the sale price. What is the total cost of the jacket?", options: ["$64.00", "$84.00", "$63.00", "$65.00"], key: "C", basis: "computed: sale price = 80 x 0.75 = 60; tax = 60 x 0.05 = 3; total = 63.00. Distractors: 64.00 = netting the percents (25 - 5 = 20% off 80); 84.00 = tax applied with no discount (80 x 1.05); 65.00 = adding 5 dollars instead of 5 percent." },
  { id: "math-68-04", subject: "math", band: "6-8", demand: "apply", strand: "ratio, rate, percent", stem: "A chess club had 40 members last year and has 50 members this year. What is the percent increase in membership?", options: ["20%", "25%", "10%", "125%"], key: "B", basis: "computed: increase = 50 - 40 = 10; 10 / 40 = 0.25 = 25%. Distractors: 20% = divided by the new amount (10/50); 10% = reported the raw difference as a percent; 125% = new amount as a percent of the old (50/40)." },
  { id: "math-68-05", subject: "math", band: "6-8", demand: "apply", strand: "ratio, rate, percent", stem: "A painter makes green paint by mixing blue paint and yellow paint in a ratio of 3:5 by volume. How much blue paint is in 40 liters of the green mixture?", options: ["24 liters", "25 liters", "15 liters", "120 liters"], key: "C", basis: "computed: 3 + 5 = 8 parts; 40 / 8 = 5 liters per part; blue = 3 x 5 = 15 liters. Distractors: 24 = treated 3:5 as the fraction 3/5 of the total (40 x 3/5); 25 = the yellow amount; 120 = 40 x 3." },
  { id: "math-68-06", subject: "math", band: "6-8", demand: "apply", strand: "integer and rational operations", stem: "What is the value of -8 + 3 x (-4) - (-6)?", options: ["-14", "26", "-26", "10"], key: "A", basis: "computed: 3 x (-4) = -12; -8 + (-12) = -20; -20 - (-6) = -20 + 6 = -14. Distractors: 26 = added before multiplying ((-8 + 3) x (-4) + 6); -26 = subtracted 6 instead of adding (-20 - 6); 10 = treated 3 x (-4) as +12." },
  { id: "math-68-07", subject: "math", band: "6-8", demand: "apply", strand: "integer and rational operations", stem: "A board is 3 1/4 feet long. A piece 1 5/6 feet long is cut from it. What is the length of the remaining board, in feet?", options: ["2 7/12", "1 5/12", "2 5/12", "5 1/12"], key: "B", basis: "computed: 3 1/4 = 39/12 and 1 5/6 = 22/12; 39/12 - 22/12 = 17/12 = 1 5/12. Distractors: 2 7/12 = subtracted the smaller fraction from the larger without regrouping (3 - 1 and 10/12 - 3/12); 2 5/12 = regrouped the fraction but did not reduce the whole number; 5 1/12 = added instead of subtracting." },
  { id: "math-68-08", subject: "math", band: "6-8", demand: "apply", strand: "integer and rational operations", stem: "A submarine is at an elevation of -120 meters. It rises 45 meters and then makes three separate dives of 20 meters each. What is its final elevation?", options: ["-225 meters", "-15 meters", "-95 meters", "-135 meters"], key: "D", basis: "computed: -120 + 45 = -75; three dives = 3 x 20 = 60; -75 - 60 = -135. Distractors: -225 = treated the rise as a descent (-120 - 45 - 60); -15 = treated the dives as rises (-75 + 60); -95 = counted only one dive (-75 - 20)." },
  { id: "math-68-09", subject: "math", band: "6-8", demand: "apply", strand: "expressions, linear equations", stem: "Which expression is equivalent to 3(2x - 5) + 4x?", options: ["10x - 15", "10x - 5", "10x + 15", "-5x"], key: "A", basis: "computed: 3(2x - 5) = 6x - 15; 6x - 15 + 4x = 10x - 15. Distractors: 10x - 5 = did not distribute 3 to the 5; 10x + 15 = sign error when distributing; -5x = wrongly combined the unlike terms 10x and -15." },
  { id: "math-68-10", subject: "math", band: "6-8", demand: "apply", strand: "expressions, linear equations", stem: "What value of x makes the equation 4x - 7 = 2x + 9 true?", options: ["x = 8", "x = 1", "x = 4", "x = 16"], key: "A", basis: "computed: 4x - 2x = 9 + 7, so 2x = 16 and x = 8; check: 4(8) - 7 = 25 and 2(8) + 9 = 25. Distractors: x = 1 = subtracted 7 from 9 instead of adding (2x = 2); x = 4 = divided 16 by 4 instead of 2; x = 16 = stopped at 2x = 16 without dividing." },
  { id: "math-68-11", subject: "math", band: "6-8", demand: "apply", strand: "expressions, linear equations", stem: "A gym charges a one-time joining fee of $30 plus $12 per month. Dana has paid the gym a total of $126. For how many months has Dana paid?", options: ["13 months", "8 months", "3 months", "10 months"], key: "B", basis: "computed: 30 + 12m = 126, so 12m = 96 and m = 8. Distractors: 13 = added the fee instead of subtracting ((126 + 30) / 12); 3 = divided the total by 30 + 12 = 42; 10 = ignored the fee and dropped the remainder of 126 / 12." },
  { id: "math-68-12", subject: "math", band: "6-8", demand: "apply", strand: "expressions, linear equations", stem: "A line passes through the points (1, 7) and (4, -2). What is the slope of the line?", options: ["-1/3", "3", "1/3", "-3"], key: "D", basis: "computed: slope = (y2 - y1)/(x2 - x1) = (-2 - 7)/(4 - 1) = -9/3 = -3. Distractors: -1/3 = change in x over change in y; 3 = sign error in the change in y; 1/3 = both errors together." },
  { id: "math-68-13", subject: "math", band: "6-8", demand: "apply", strand: "expressions, linear equations", stem: "Which inequality gives all solutions of -3x + 5 > 17?", options: ["x > -4", "x < -4", "x < 4", "x > 4"], key: "B", basis: "computed: -3x > 12; dividing by -3 reverses the inequality, so x < -4; check x = -5: 15 + 5 = 20 > 17. Distractors: x > -4 = did not reverse the inequality sign; x < 4 = reversed the sign but lost the negative; x > 4 = lost the negative and did not reverse." },
  { id: "math-68-14", subject: "math", band: "6-8", demand: "apply", strand: "area, volume, angles, Pythagoras", stem: "A trapezoid has parallel sides of length 8 centimeters and 14 centimeters. The perpendicular distance between the parallel sides is 5 centimeters. What is the area of the trapezoid?", options: ["110 square centimeters", "560 square centimeters", "55 square centimeters", "27 square centimeters"], key: "C", basis: "computed: area of a trapezoid = (1/2)(b1 + b2)h = (1/2)(8 + 14)(5) = (1/2)(22)(5) = 55. Distractors: 110 = omitted the factor of 1/2; 560 = multiplied all three lengths; 27 = added all three lengths." },
  { id: "math-68-15", subject: "math", band: "6-8", demand: "apply", strand: "area, volume, angles, Pythagoras", stem: "A cylindrical can has a diameter of 6 centimeters and a height of 10 centimeters. What is the volume of the can, in terms of pi?", options: ["90 pi cubic centimeters", "360 pi cubic centimeters", "60 pi cubic centimeters", "30 pi cubic centimeters"], key: "A", basis: "computed: radius = 6/2 = 3; V = pi r^2 h = pi x 9 x 10 = 90 pi. Distractors: 360 pi = used the diameter as the radius (36 x 10); 60 pi = used pi x diameter x height (the lateral area formula); 30 pi = did not square the radius (3 x 10)." },
  { id: "math-68-16", subject: "math", band: "6-8", demand: "apply", strand: "area, volume, angles, Pythagoras", stem: "Two interior angles of a triangle measure 48 degrees and 67 degrees. What is the measure of an exterior angle at the third vertex of the triangle?", options: ["115 degrees", "65 degrees", "245 degrees", "25 degrees"], key: "A", basis: "computed: third interior angle = 180 - 48 - 67 = 65; exterior angle = 180 - 65 = 115 (equivalently 48 + 67 = 115, exterior angle theorem). Distractors: 65 = gave the third interior angle; 245 = subtracted the two angles from 360; 25 = subtracted the third interior angle from 90." },
  { id: "math-68-17", subject: "math", band: "6-8", demand: "apply", strand: "area, volume, angles, Pythagoras", stem: "A straight support wire 25 feet long runs from the top of a vertical pole to a point on level ground 7 feet from the base of the pole. How tall is the pole?", options: ["18 feet", "32 feet", "24 feet", "576 feet"], key: "C", basis: "computed (Pythagorean theorem): height^2 = 25^2 - 7^2 = 625 - 49 = 576; height = sqrt(576) = 24. Distractors: 18 = subtracted the lengths (25 - 7); 32 = added the lengths (25 + 7); 576 = did not take the square root." },
  { id: "math-68-18", subject: "math", band: "6-8", demand: "apply", strand: "statistics, probability", stem: "After four quizzes, Malik's mean quiz score is 82. What score does he need on the fifth quiz so that his mean for all five quizzes is 84?", options: ["86", "84", "90", "92"], key: "D", basis: "computed: total needed = 5 x 84 = 420; current total = 4 x 82 = 328; 420 - 328 = 92. Distractors: 86 = averaged only 82 and the new score ((82 + 86)/2 = 84); 84 = assumed scoring the target mean is enough; 90 = added the 8 make-up points to 82 instead of to 84." },
  { id: "math-68-19", subject: "math", band: "6-8", demand: "apply", strand: "statistics, probability", stem: "A bag holds 4 red, 6 blue, and 2 green marbles. One marble is drawn at random, put back in the bag, and then a second marble is drawn at random. What is the probability that the first marble is red and the second marble is green?", options: ["1/2", "2/33", "1/6", "1/18"], key: "D", basis: "computed: total = 12; P(red) = 4/12 = 1/3; with replacement P(green) = 2/12 = 1/6; (1/3)(1/6) = 1/18. Distractors: 1/2 = added the probabilities (4/12 + 2/12); 2/33 = treated the draws as without replacement (4/12 x 2/11); 1/6 = gave only the probability of green." },
  { id: "math-68-20", subject: "math", band: "6-8", demand: "apply", strand: "statistics, probability", stem: "The numbers of books read by eight students are 12, 7, 9, 15, 7, 10, 18, and 6. What is the median number of books read?", options: ["10.5", "7.0", "12.0", "9.5"], key: "D", basis: "computed: ordered data 6, 7, 7, 9, 10, 12, 15, 18; median = mean of 4th and 5th values = (9 + 10)/2 = 9.5. Distractors: 10.5 = the mean (84/8); 7.0 = the mode; 12.0 = the range (18 - 6)." },
  { id: "math-912-01", subject: "math", band: "9-12", demand: "apply", strand: "quadratics, systems, exponents", stem: "What is the larger of the two solutions of the equation x^2 - 5x - 14 = 0?", options: ["2", "5", "7", "14"], key: "C", basis: "computed: x^2 - 5x - 14 = (x - 7)(x + 2) = 0, so x = 7 or x = -2; the larger is 7. Distractors: 2 from sign-flipped factors, 5 is the sum of the roots, 14 is the constant term." },
  { id: "math-912-02", subject: "math", band: "9-12", demand: "apply", strand: "quadratics, systems, exponents", stem: "A school play sold 60 tickets in all. Adult tickets cost 8 dollars each and student tickets cost 5 dollars each. Total ticket sales were 414 dollars. How many adult tickets were sold?", options: ["22", "30", "52", "38"], key: "D", basis: "computed: a + s = 60 and 8a + 5s = 414. Substituting s = 60 - a: 8a + 300 - 5a = 414, 3a = 114, a = 38. Check: 38*8 + 22*5 = 304 + 110 = 414. Distractors: 22 is the student count, 30 splits the tickets evenly, 52 is 414/8 rounded." },
  { id: "math-912-03", subject: "math", band: "9-12", demand: "apply", strand: "quadratics, systems, exponents", stem: "Which expression is equivalent to (2x^3 y)^2 * x^(-4) for nonzero x?", options: ["2x^2 y^2", "4x y^2", "4x^10 y^2", "4x^2 y^2"], key: "D", basis: "computed: (2x^3 y)^2 = 4x^6 y^2; multiplying by x^(-4) gives 4x^(6-4) y^2 = 4x^2 y^2. Distractors: coefficient not squared; exponents 3 and 2 added instead of multiplied (x^5 * x^-4 = x); exponent -4 subtracted as 6 - (-4) = 10." },
  { id: "math-912-04", subject: "math", band: "9-12", demand: "apply", strand: "quadratics, systems, exponents", stem: "What is the minimum value of the function f(x) = 2x^2 - 12x + 7?", options: ["-11", "3", "7", "61"], key: "A", basis: "computed: vertex at x = -b/(2a) = 12/4 = 3; f(3) = 2(9) - 36 + 7 = -11. Distractors: 3 is the x-coordinate of the vertex, 7 is the y-intercept, 61 is f(-3) from a sign error in the vertex formula." },
  { id: "math-912-05", subject: "math", band: "9-12", demand: "apply", strand: "quadratics, systems, exponents", stem: "For what value of k does the equation x^2 + 6x + k = 0 have exactly one real solution?", options: ["3", "9", "12", "36"], key: "B", basis: "computed: one real solution requires discriminant 0: 6^2 - 4(1)(k) = 0, so 36 = 4k and k = 9 (x^2 + 6x + 9 = (x + 3)^2). Distractors: 3 is half of b, 12 is 2b, 36 is b^2 without dividing by 4." },
  { id: "math-912-06", subject: "math", band: "9-12", demand: "apply", strand: "quadratics, systems, exponents", stem: "What value of x satisfies the equation 4^(x+1) = 8^(x-1)?", options: ["3", "5", "2", "-5"], key: "B", basis: "computed: rewrite in base 2: 2^(2x+2) = 2^(3x-3), so 2x + 2 = 3x - 3 and x = 5. Check: 4^6 = 4096 = 8^4. Distractors: 3 from treating 8 as 4^2; 2 from not distributing the exponents (2x + 1 = 3x - 1); -5 from a sign error." },
  { id: "math-912-07", subject: "math", band: "9-12", demand: "apply", strand: "quadratics, systems, exponents", stem: "The length of a rectangular garden is 3 meters more than its width, and its area is 70 square meters. What is the perimeter of the garden, in meters?", options: ["34", "17", "38", "73"], key: "A", basis: "computed: w(w + 3) = 70 gives w^2 + 3w - 70 = 0, (w + 10)(w - 7) = 0, w = 7, length = 10; perimeter = 2(7 + 10) = 34. Distractors: 17 is length plus width only; 38 uses the factor pair 5 by 14, which does not differ by 3; 73 adds 70 and 3." },
  { id: "math-912-08", subject: "math", band: "9-12", demand: "apply", strand: "linear, exponential, log functions", stem: "A line passes through the points (2, 5) and (6, -3). What is the y-intercept of the line?", options: ["1", "-2", "9", "6"], key: "C", basis: "computed: slope = (-3 - 5)/(6 - 2) = -8/4 = -2; y = -2x + b; 5 = -4 + b, so b = 9. Check: -2(6) + 9 = -3. Distractors: 1 from using slope +2; -2 is the slope; 6 from using the inverted slope -1/2." },
  { id: "math-912-09", subject: "math", band: "9-12", demand: "apply", strand: "linear, exponential, log functions", stem: "A culture starts with 500 bacteria, and the number of bacteria doubles every 3 hours. How many bacteria are in the culture after 12 hours?", options: ["4000", "2000", "6000", "8000"], key: "D", basis: "computed: 12 hours / 3 hours = 4 doublings; 500 * 2^4 = 500 * 16 = 8000. Distractors: 4000 from 500 * 2 * 4 (linear growth); 2000 from 500 * 4; 6000 from 500 * 12." },
  { id: "math-912-10", subject: "math", band: "9-12", demand: "apply", strand: "linear, exponential, log functions", stem: "If the logarithm base 2 of (x - 3) equals 4, what is the value of x?", options: ["11", "13", "16", "19"], key: "D", basis: "computed: log_2(x - 3) = 4 means x - 3 = 2^4 = 16, so x = 19. Distractors: 11 from 2*4 + 3; 13 from 16 - 3; 16 from forgetting to add 3." },
  { id: "math-912-11", subject: "math", band: "9-12", demand: "apply", strand: "linear, exponential, log functions", stem: "A machine is purchased for $15,000, and its value decreases by 20% each year. What is the value of the machine after 2 years?", options: ["$9,000", "$12,000", "$9,600", "$600"], key: "C", basis: "computed: 15,000 * 0.8^2 = 15,000 * 0.64 = 9,600. Distractors: $9,000 from subtracting 40% linearly; $12,000 is the value after one year; $600 from multiplying by 0.2^2 instead of 0.8^2." },
  { id: "math-912-12", subject: "math", band: "9-12", demand: "apply", strand: "geometry, trigonometry", stem: "What is the distance between the points (-2, 3) and (6, -12) in the coordinate plane?", options: ["23", "7", "17", "289"], key: "C", basis: "computed: distance = sqrt((6 - (-2))^2 + (-12 - 3)^2) = sqrt(8^2 + 15^2) = sqrt(64 + 225) = sqrt(289) = 17. Distractors: 23 from adding the horizontal and vertical changes (8 + 15); 7 from subtracting them (15 - 8); 289 from forgetting the square root." },
  { id: "math-912-13", subject: "math", band: "9-12", demand: "apply", strand: "geometry, trigonometry", stem: "In a right triangle, acute angle A satisfies sin A = 5/13. What is the value of tan A?", options: ["5/12", "12/13", "12/5", "13/5"], key: "A", basis: "computed: opposite = 5, hypotenuse = 13, adjacent = sqrt(169 - 25) = 12; tan A = opposite/adjacent = 5/12. Distractors: 12/13 is cos A; 12/5 is the reciprocal (cot A); 13/5 is csc A." },
  { id: "math-912-14", subject: "math", band: "9-12", demand: "apply", strand: "geometry, trigonometry", stem: "A circle has a radius of 6 centimeters. What is the area, in square centimeters, of a sector of the circle with a central angle of 60 degrees?", options: ["2pi", "12pi", "36pi", "6pi"], key: "D", basis: "computed: sector area = (60/360) * pi * 6^2 = (1/6)(36pi) = 6pi. Distractors: 2pi is the arc length of the sector; 12pi is the circumference; 36pi is the area of the whole circle." },
  { id: "math-912-15", subject: "math", band: "9-12", demand: "apply", strand: "geometry, trigonometry", stem: "From a point on level ground 40 meters from the base of a vertical tower, the angle of elevation to the top of the tower is 60 degrees. To the nearest tenth of a meter, how tall is the tower?", options: ["69.3", "34.6", "23.1", "20.0"], key: "A", basis: "computed: height = 40 * tan(60 degrees) = 40 * sqrt(3) = 69.28, which rounds to 69.3. Distractors: 34.6 from 40 * sin 60; 23.1 from 40 / tan 60; 20.0 from 40 * cos 60." },
  { id: "math-912-16", subject: "math", band: "9-12", demand: "apply", strand: "statistics, probability", stem: "The mean of five test scores is 82. Four of the scores are 75, 80, 88, and 90. What is the fifth score?", options: ["82", "77", "83", "67"], key: "B", basis: "computed: total = 5 * 82 = 410; known sum = 75 + 80 + 88 + 90 = 333; fifth score = 410 - 333 = 77. Distractors: 82 assumes the missing score equals the mean; 83 is the rounded mean of the four known scores; 67 from using a total of 400." },
  { id: "math-912-17", subject: "math", band: "9-12", demand: "apply", strand: "statistics, probability", stem: "A bag contains 4 red marbles and 6 blue marbles. Two marbles are drawn at random, one after the other, without replacement. What is the probability that both marbles are red?", options: ["4/25", "2/5", "2/15", "1/3"], key: "C", basis: "computed: (4/10) * (3/9) = 12/90 = 2/15. Distractors: 4/25 from drawing with replacement (4/10 * 4/10); 2/5 is the probability for one draw only; 1/3 is only the second-draw conditional probability 3/9." },
  { id: "math-912-18", subject: "math", band: "9-12", demand: "apply", strand: "statistics, probability", stem: "In a survey of 200 students, 120 play a sport, 90 play a musical instrument, and 50 do both. If a student who plays a sport is chosen at random, what is the probability that the student also plays a musical instrument?", options: ["1/4", "5/12", "5/9", "9/20"], key: "B", basis: "computed: conditional probability P(instrument | sport) = 50/120 = 5/12. Distractors: 1/4 from 50/200 (not conditioning); 5/9 from 50/90 (conditioning on the wrong group); 9/20 from 90/200 (ignoring the condition entirely)." },
  { id: "math-912-19", subject: "math", band: "9-12", demand: "apply", strand: "sequences", stem: "In an arithmetic sequence, the 3rd term is 11 and the 7th term is 27. What is the 20th term?", options: ["79", "80", "83", "87"], key: "A", basis: "computed: 4d = 27 - 11 = 16, so d = 4; first term = 11 - 2(4) = 3; 20th term = 3 + 19(4) = 79. Distractors: 80 from 20 * 4; 83 from 3 + 20 * 4; 87 from 11 + 19 * 4 (treating the 3rd term as the first)." },
  { id: "math-912-20", subject: "math", band: "9-12", demand: "apply", strand: "sequences", stem: "A geometric sequence has first term 3 and common ratio 2. What is the sum of the first 6 terms?", options: ["96", "189", "192", "93"], key: "B", basis: "computed: 3 + 6 + 12 + 24 + 48 + 96 = 189; equivalently 3(2^6 - 1)/(2 - 1) = 3 * 63 = 189. Distractors: 96 is the 6th term alone; 192 is 3 * 2^6 without subtracting 1; 93 is the sum of only five terms." },
  { id: "science-k5-01", subject: "science", band: "K-5", demand: "recall", strand: "life science", stem: "Which part of a plant takes in most of the water the plant needs from the soil?", options: ["Leaves", "Flowers", "Roots", "Stem"], key: "C", basis: "Plant structure and function: roots absorb water and minerals from soil; stems transport it, leaves make food, flowers reproduce." },
  { id: "science-k5-02", subject: "science", band: "K-5", demand: "apply", strand: "life science", stem: "In a meadow, grasshoppers eat grass, frogs eat grasshoppers, and snakes eat frogs. If a disease suddenly kills most of the frogs, what will most likely happen to the grasshoppers at first?", options: ["Their numbers will go down", "Their numbers will go up", "Their numbers will stay the same", "They will start eating snakes"], key: "B", basis: "Food chain reasoning: removing a predator (frogs) reduces predation on its prey (grasshoppers), so the prey population rises at first." },
  { id: "science-k5-03", subject: "science", band: "K-5", demand: "recall", strand: "life science", stem: "Green plants make their own food by photosynthesis. Which three things do they use to do this?", options: ["Sunlight, soil, and oxygen", "Water, soil, and oxygen", "Sunlight, water, and carbon dioxide", "Soil, water, and sugar"], key: "C", basis: "Photosynthesis: plants use light energy, water, and carbon dioxide to make sugar and release oxygen; soil is not a food ingredient and sugar is the product." },
  { id: "science-k5-04", subject: "science", band: "K-5", demand: "apply", strand: "life science", stem: "Which of these traits of a pet dog is inherited from its parents rather than learned?", options: ["Sitting when it is told to", "Knowing the way to the park", "The color of its fur", "Coming when a whistle blows"], key: "C", basis: "Inherited traits (such as fur color) are passed from parents through genes; sitting on command, knowing a route, and answering a whistle are learned behaviors." },
  { id: "science-k5-05", subject: "science", band: "K-5", demand: "apply", strand: "life science", stem: "A scientist describes an animal that has thick white fur, a deep layer of body fat, and very small ears. For which habitat is this animal best suited?", options: ["A hot, dry desert", "A warm, rainy forest", "A cold, snowy tundra", "A sunny, grassy plain"], key: "C", basis: "Adaptations: thick fur and fat insulate against cold, small ears reduce heat loss, and white fur camouflages against snow, so the animal fits a cold, snowy habitat." },
  { id: "science-k5-06", subject: "science", band: "K-5", demand: "recall", strand: "life science", stem: "A butterfly's life cycle has four stages. Which stage comes right after the caterpillar (larva) stage?", options: ["Pupa", "Egg", "Adult", "Tadpole"], key: "A", basis: "Complete metamorphosis in butterflies: egg, larva (caterpillar), pupa (chrysalis), adult." },
  { id: "science-k5-07", subject: "science", band: "K-5", demand: "recall", strand: "earth and space", stem: "What causes day and night on Earth?", options: ["Earth spinning on its axis", "Earth traveling around the Sun", "The Sun traveling around Earth", "The Moon blocking the Sun's light"], key: "A", basis: "Earth rotates on its axis about once every 24 hours, so each place turns toward the Sun (day) and away from it (night); the orbit around the Sun takes a year." },
  { id: "science-k5-08", subject: "science", band: "K-5", demand: "apply", strand: "earth and space", stem: "On a clear day, a flagpole casts a short shadow at noon. How will the flagpole's shadow look shortly before sunset on the same day?", options: ["Shorter, pointing away from the Sun", "Longer, pointing toward the Sun", "The same length, pointing toward the Sun", "Longer, pointing away from the Sun"], key: "D", basis: "Shadows always fall on the side opposite the light source, and they lengthen as the Sun gets lower in the sky, so near sunset the shadow is long and points away from the Sun." },
  { id: "science-k5-09", subject: "science", band: "K-5", demand: "apply", strand: "earth and space", stem: "A puddle on a sidewalk slowly disappears during a warm, sunny afternoon, even though no one touches it. Which process moved the water into the air?", options: ["Condensation", "Precipitation", "Melting", "Evaporation"], key: "D", basis: "Water cycle: evaporation is liquid water changing to water vapor when heated; condensation is vapor to liquid, precipitation is water falling, melting is solid to liquid." },
  { id: "science-k5-10", subject: "science", band: "K-5", demand: "recall", strand: "earth and space", stem: "Over a very long time, layers of sand and mud at the bottom of a lake are pressed and cemented together into rock. What type of rock forms this way?", options: ["Sedimentary", "Igneous", "Metamorphic", "Volcanic"], key: "A", basis: "Rock classification: sedimentary rock forms from compacted and cemented layers of sediment; igneous (including volcanic) rock forms from cooled molten rock, and metamorphic rock from heat and pressure changing existing rock." },
  { id: "science-k5-11", subject: "science", band: "K-5", demand: "recall", strand: "earth and space", stem: "Why are summers warmer than winters in places far from the equator?", options: ["Earth moves much closer to the Sun in summer", "The Sun gives off more heat in summer months", "Earth spins more slowly in the summer months", "Earth's tilted axis makes sunlight more direct"], key: "D", basis: "Seasons are caused by the tilt of Earth's axis (about 23.5 degrees): the hemisphere tilted toward the Sun gets more direct sunlight and longer days. Distance from the Sun is not the cause." },
  { id: "science-k5-12", subject: "science", band: "K-5", demand: "recall", strand: "matter, forces, energy", stem: "Which state of matter keeps the same volume but takes the shape of whatever container it is poured into?", options: ["Solid", "Gas", "Steam", "Liquid"], key: "D", basis: "Properties of states of matter: a liquid has a definite volume but no definite shape; a solid has both; a gas (including steam) has neither." },
  { id: "science-k5-13", subject: "science", band: "K-5", demand: "apply", strand: "matter, forces, energy", stem: "Lena holds the north pole of one bar magnet close to the north pole of another bar magnet. What will she feel?", options: ["The magnets pull toward each other", "The magnets push away from each other", "The magnets feel no force at all", "The magnets pull first, then push apart"], key: "B", basis: "Law of magnetic poles: like poles repel and unlike poles attract, so two north poles push apart." },
  { id: "science-k5-14", subject: "science", band: "K-5", demand: "apply", strand: "matter, forces, energy", stem: "In which of these changes is a new substance formed?", options: ["An ice cube melting", "A sheet of paper being torn", "An iron nail rusting", "Sugar dissolving in water"], key: "C", basis: "Rusting is a chemical change: iron reacts with oxygen and water to form iron oxide, a new substance. Melting, tearing, and dissolving are physical changes in which the substances stay the same." },
  { id: "science-k5-15", subject: "science", band: "K-5", demand: "apply", strand: "matter, forces, energy", stem: "A student stirs 50 grams of salt into 200 grams of water until no salt can be seen. What is the mass of the salt water?", options: ["200 grams", "150 grams", "50 grams", "250 grams"], key: "D", basis: "Conservation of matter; computed: 50 g + 200 g = 250 g. Distractors: 200 (salt thought to vanish), 150 (subtracted), 50 (only the salt counted)." },
  { id: "science-k5-16", subject: "science", band: "K-5", demand: "apply", strand: "matter, forces, energy", stem: "Omar gives a toy car the same push on four different flat surfaces. On which surface will the car roll the farthest before stopping?", options: ["Thick carpet", "Smooth tile floor", "Rough sandpaper", "Dry grass lawn"], key: "B", basis: "Friction opposes motion and is smallest on the smoothest surface, so the car loses speed most slowly on smooth tile and travels farthest." },
  { id: "science-k5-17", subject: "science", band: "K-5", demand: "recall", strand: "matter, forces, energy", stem: "Before a flashlight is switched on, what form of energy is stored inside its battery?", options: ["Light energy", "Chemical energy", "Sound energy", "Motion energy"], key: "B", basis: "A battery stores chemical energy, which is changed to electrical energy in the circuit and then to light (and heat) in the bulb." },
  { id: "science-k5-18", subject: "science", band: "K-5", demand: "recall", strand: "measurement and scientific method", stem: "Which tool should a student use to measure out 40 milliliters of water?", options: ["A graduated cylinder", "A double-pan balance", "A thermometer", "A meter stick"], key: "A", basis: "A graduated cylinder measures liquid volume in milliliters; a balance measures mass, a thermometer temperature, and a meter stick length." },
  { id: "science-k5-19", subject: "science", band: "K-5", demand: "apply", strand: "measurement and scientific method", stem: "Priya wants to find out whether the amount of water affects how tall bean plants grow. She sets up four pots. To make it a fair test, what is the one thing that should be different from pot to pot?", options: ["The kind of plant in each pot", "How much water each pot gets", "How much sunlight each pot gets", "The kind of soil in each pot"], key: "B", basis: "Fair test (controlled experiment): only the variable being tested, here the amount of water, is changed; plant type, sunlight, and soil are kept the same." },
  { id: "science-k5-20", subject: "science", band: "K-5", demand: "apply", strand: "measurement and scientific method", stem: "A thermometer outside a classroom reads 8 degrees Celsius at 7 in the morning and 23 degrees Celsius at 2 in the afternoon. By how many degrees did the temperature rise?", options: ["15 degrees Celsius", "31 degrees Celsius", "25 degrees Celsius", "16 degrees Celsius"], key: "A", basis: "Computed: 23 - 8 = 15. Distractors: 31 (added 23 + 8), 25 (regrouping error: 13 - 8 = 5 but tens digit left as 2), 16 (counted both end values)." },
  { id: "science-68-01", subject: "science", band: "6-8", demand: "recall", strand: "cells, heredity, ecosystems", stem: "Which cell structure releases most of the usable energy from sugar during cellular respiration?", options: ["Chloroplast", "Ribosome", "Mitochondrion", "Nucleus"], key: "C", basis: "Cell biology: aerobic cellular respiration takes place mainly in the mitochondria, which produce most of a cell's ATP. Chloroplasts carry out photosynthesis, ribosomes build proteins, and the nucleus stores DNA." },
  { id: "science-68-02", subject: "science", band: "6-8", demand: "apply", strand: "cells, heredity, ecosystems", stem: "In pea plants, the allele for tall stems (T) is dominant over the allele for short stems (t). A plant with genotype Tt is crossed with a plant with genotype tt. What percentage of the offspring are expected to have short stems?", options: ["50%", "25%", "75%", "0%"], key: "A", basis: "Punnett square Tt x tt gives offspring Tt, Tt, tt, tt. Two of four are tt (short), so 2/4 = 50%. 25% is the result for Tt x Tt; 75% is the tall fraction for Tt x Tt; 0% assumes the dominant trait always shows." },
  { id: "science-68-03", subject: "science", band: "6-8", demand: "apply", strand: "cells, heredity, ecosystems", stem: "In a meadow, grass is eaten by grasshoppers, grasshoppers are eaten by frogs, and frogs are eaten by snakes. A disease suddenly kills most of the frogs. What is the most likely short-term result?", options: ["Grasshoppers decrease and snakes increase", "Grasshoppers increase and snakes decrease", "Grasshoppers and snakes both increase", "Grasshoppers and snakes both decrease"], key: "B", basis: "Food chain reasoning: with fewer frogs, their prey (grasshoppers) face less predation and increase, while their predators (snakes) lose their food source and decrease." },
  { id: "science-68-04", subject: "science", band: "6-8", demand: "apply", strand: "cells, heredity, ecosystems", stem: "A red blood cell is placed in a beaker of very salty water. The concentration of dissolved salt is much higher outside the cell than inside it. What happens to the cell?", options: ["Water enters the cell, and the cell swells", "Salt enters the cell, and the cell swells", "Nothing moves, and the cell stays the same size", "Water leaves the cell, and the cell shrinks"], key: "D", basis: "Osmosis: water moves across a selectively permeable membrane toward the side with the higher solute concentration. In a hypertonic solution, water moves out of the cell and the cell shrinks." },
  { id: "science-68-05", subject: "science", band: "6-8", demand: "recall", strand: "cells, heredity, ecosystems", stem: "Which two substances does a green plant take in and use as the raw materials for making sugar during photosynthesis?", options: ["Oxygen and glucose", "Oxygen and water", "Carbon dioxide and glucose", "Carbon dioxide and water"], key: "D", basis: "Photosynthesis: carbon dioxide + water, with light energy, yields glucose + oxygen. The reactants are carbon dioxide and water; glucose and oxygen are products." },
  { id: "science-68-06", subject: "science", band: "6-8", demand: "apply", strand: "cells, heredity, ecosystems", stem: "In a grassland, the producers store 10,000 kJ of energy. About 10% of the energy at each feeding level is passed on to the next level. About how much energy is available to the secondary consumers, the animals that eat the plant-eaters?", options: ["1,000 kJ", "100 kJ", "10 kJ", "9,000 kJ"], key: "B", basis: "Computed: producers 10,000 kJ; primary consumers 10% of 10,000 = 1,000 kJ; secondary consumers 10% of 1,000 = 100 kJ. 1,000 kJ is only one transfer; 10 kJ is three transfers; 9,000 kJ subtracts 10% once." },
  { id: "science-68-07", subject: "science", band: "6-8", demand: "apply", strand: "motion, energy, waves", stem: "A cyclist rides 45 km along a straight trail in 3 hours. What is the cyclist's average speed?", options: ["135 km/h", "48 km/h", "42 km/h", "15 km/h"], key: "D", basis: "Computed: average speed = distance / time = 45 km / 3 h = 15 km/h. 135 comes from multiplying, 48 from adding, 42 from subtracting." },
  { id: "science-68-08", subject: "science", band: "6-8", demand: "apply", strand: "motion, energy, waves", stem: "A net force of 30 N acts on a cart and gives it an acceleration of 6 m/s^2. What is the mass of the cart?", options: ["180 kg", "36 kg", "5 kg", "24 kg"], key: "C", basis: "Newton's second law, F = ma, so m = F / a = 30 N / 6 m/s^2 = 5 kg. 180 comes from multiplying, 36 from adding, 24 from subtracting." },
  { id: "science-68-09", subject: "science", band: "6-8", demand: "apply", strand: "motion, energy, waves", stem: "A ball is dropped from a balcony and falls toward the ground. Ignoring air resistance, what happens to the ball's energy as it falls?", options: ["Kinetic energy decreases and gravitational potential energy increases", "Kinetic energy and gravitational potential energy both increase", "Kinetic energy and gravitational potential energy both stay the same", "Kinetic energy increases and gravitational potential energy decreases"], key: "D", basis: "Conservation of mechanical energy: as height decreases, gravitational potential energy (mgh) decreases, and it is converted to kinetic energy (1/2 mv^2) as the ball speeds up. The total stays constant, not each form." },
  { id: "science-68-10", subject: "science", band: "6-8", demand: "recall", strand: "motion, energy, waves", stem: "Which type of wave must have matter to travel through and therefore cannot cross empty space?", options: ["Radio wave", "Visible light wave", "Sound wave", "X-ray"], key: "C", basis: "Sound is a mechanical wave that requires a medium (solid, liquid or gas). Radio waves, visible light and X-rays are electromagnetic waves, which can travel through a vacuum." },
  { id: "science-68-11", subject: "science", band: "6-8", demand: "apply", strand: "motion, energy, waves", stem: "A water wave has a frequency of 6 Hz and a wavelength of 3 m. What is the speed of the wave?", options: ["18 m/s", "2 m/s", "9 m/s", "3 m/s"], key: "A", basis: "Wave equation: speed = frequency x wavelength = 6 Hz x 3 m = 18 m/s. 2 comes from dividing, 9 from adding, 3 from subtracting." },
  { id: "science-68-12", subject: "science", band: "6-8", demand: "apply", strand: "atoms, periodic table, reactions", stem: "A neutral atom has 6 protons, 7 neutrons and 6 electrons. What is the mass number of this atom?", options: ["13", "12", "19", "6"], key: "A", basis: "Mass number = protons + neutrons = 6 + 7 = 13. 12 adds protons and electrons, 19 adds all three particle counts, and 6 is the atomic number." },
  { id: "science-68-13", subject: "science", band: "6-8", demand: "recall", strand: "atoms, periodic table, reactions", stem: "Sodium and potassium are in the same column of the periodic table. Which statement best explains why these two elements react in similar ways?", options: ["Their atoms have the same number of protons", "Their atoms have the same number of outer-shell electrons", "Their atoms have the same number of electron shells", "Their atoms have the same total mass"], key: "B", basis: "Periodic law: elements in the same group have the same number of valence electrons (one each for sodium and potassium), which determines chemical behavior. Same number of shells describes a period, and proton count and mass differ between elements." },
  { id: "science-68-14", subject: "science", band: "6-8", demand: "apply", strand: "atoms, periodic table, reactions", stem: "A 24 g strip of magnesium burns completely in oxygen. The only product is 40 g of magnesium oxide. What mass of oxygen combined with the magnesium?", options: ["64 g", "40 g", "16 g", "24 g"], key: "C", basis: "Law of conservation of mass: mass of reactants = mass of products, so oxygen = 40 g - 24 g = 16 g. 64 g comes from adding, 40 g repeats the product mass, 24 g assumes equal masses of each reactant." },
  { id: "science-68-15", subject: "science", band: "6-8", demand: "apply", strand: "atoms, periodic table, reactions", stem: "The formula for carbon dioxide is CO2. How many oxygen atoms are in three molecules of carbon dioxide?", options: ["6", "2", "3", "9"], key: "A", basis: "Computed: each CO2 molecule has 2 oxygen atoms; 3 molecules x 2 = 6 oxygen atoms. 2 ignores the number of molecules, 3 counts molecules, 9 counts all atoms (3 carbon + 6 oxygen)." },
  { id: "science-68-16", subject: "science", band: "6-8", demand: "apply", strand: "atoms, periodic table, reactions", stem: "Which of these changes produces a new substance with different chemical properties?", options: ["Sugar dissolves in warm tea", "An ice cube melts on a plate", "An iron nail rusts in damp air", "A glass bottle shatters on the floor"], key: "C", basis: "Rusting is a chemical change: iron reacts with oxygen and water to form iron oxide, a new substance. Dissolving, melting and breaking are physical changes in which the substance keeps its identity." },
  { id: "science-68-17", subject: "science", band: "6-8", demand: "recall", strand: "earth and space", stem: "What is the main cause of the yearly cycle of summer and winter in Earth's Northern Hemisphere?", options: ["Earth moves closer to and farther from the Sun during the year", "Earth spins faster and slower on its axis during the year", "The Sun gives off more and less energy during the year", "Earth's axis is tilted relative to its orbit around the Sun"], key: "D", basis: "Seasons result from Earth's axial tilt of about 23.5 degrees, which changes the angle of sunlight and day length through the year. Earth is actually closest to the Sun during Northern Hemisphere winter, so distance is not the cause." },
  { id: "science-68-18", subject: "science", band: "6-8", demand: "apply", strand: "earth and space", stem: "The Moon is on the opposite side of Earth from the Sun, but it is not inside Earth's shadow. Which phase of the Moon does a person on Earth see that night?", options: ["Full moon", "New moon", "First quarter moon", "Waxing crescent moon"], key: "A", basis: "Lunar phases: when the Moon is opposite the Sun as seen from Earth, its entire Earth-facing side is sunlit, which is a full moon. A new moon occurs when the Moon is between Earth and the Sun." },
  { id: "science-68-19", subject: "science", band: "6-8", demand: "apply", strand: "earth and space", stem: "Two tectonic plates that both carry thick continental crust slowly push into each other for millions of years. Which landform is most likely to form where they meet?", options: ["A mid-ocean ridge", "A tall folded mountain range", "A wide rift valley", "A chain of volcanic islands"], key: "B", basis: "Plate tectonics: at a continental-continental convergent boundary neither plate subducts easily, so crust crumples and thickens into folded mountains. Ridges and rift valleys form at divergent boundaries; volcanic island chains form where oceanic plates subduct." },
  { id: "science-68-20", subject: "science", band: "6-8", demand: "recall", strand: "earth and space", stem: "In the water cycle, which process changes water vapor in rising air into the tiny liquid droplets that make up a cloud?", options: ["Evaporation", "Condensation", "Precipitation", "Transpiration"], key: "B", basis: "Water cycle: condensation is the change of state from gas (water vapor) to liquid as air cools. Evaporation and transpiration turn liquid water into vapor; precipitation is water falling from clouds." },
  { id: "science-912-01", subject: "science", band: "9-12", demand: "recall", strand: "biology", stem: "In a eukaryotic cell, which structure is the main site of ATP production during aerobic cellular respiration?", options: ["Ribosome", "Golgi apparatus", "Mitochondrion", "Nucleus"], key: "C", basis: "Cell biology: the Krebs cycle and electron transport chain, which produce most ATP in aerobic respiration, occur in the mitochondrion." },
  { id: "science-912-02", subject: "science", band: "9-12", demand: "apply", strand: "biology", stem: "In a species of pea plant, the allele for purple flowers (P) is completely dominant over the allele for white flowers (p). Two heterozygous plants (Pp x Pp) are crossed and produce 200 offspring. About how many of the offspring are expected to have white flowers?", options: ["100", "150", "25", "50"], key: "D", basis: "computed: Pp x Pp gives 1 PP : 2 Pp : 1 pp, so 1/4 are white; 1/4 x 200 = 50. Distractors: 100 = heterozygote fraction (1/2), 150 = purple fraction (3/4), 25 = 1/8." },
  { id: "science-912-03", subject: "science", band: "9-12", demand: "apply", strand: "biology", stem: "Analysis of a sample of double-stranded DNA shows that 22% of its bases are adenine. What percentage of the bases in this sample are cytosine?", options: ["22%", "28%", "56%", "78%"], key: "B", basis: "computed: base pairing (Chargaff's rules) gives A = T = 22%, so A + T = 44%; G + C = 56%; C = 56/2 = 28%. Distractors: 22% = assumes C equals A, 56% = forgot to halve G + C, 78% = 100 - 22." },
  { id: "science-912-04", subject: "science", band: "9-12", demand: "apply", strand: "biology", stem: "In a grassland ecosystem, the producers store 20,000 kJ of energy. Assuming that about 10% of the energy at each trophic level is passed to the next level, how much energy is available to the tertiary consumers?", options: ["200 kJ", "20 kJ", "2,000 kJ", "2 kJ"], key: "B", basis: "computed: producers 20,000 kJ -> primary consumers 2,000 kJ -> secondary consumers 200 kJ -> tertiary consumers 20 kJ (three transfers of 10%). Distractors are one transfer too few (200), two too few (2,000) and one too many (2)." },
  { id: "science-912-05", subject: "science", band: "9-12", demand: "recall", strand: "biology", stem: "During protein synthesis, which molecule carries individual amino acids to the ribosome and matches them to the codons of the genetic message?", options: ["Messenger RNA", "Ribosomal RNA", "DNA polymerase", "Transfer RNA"], key: "D", basis: "Molecular biology: tRNA molecules carry specific amino acids and pair their anticodons with mRNA codons during translation." },
  { id: "science-912-06", subject: "science", band: "9-12", demand: "apply", strand: "biology", stem: "A population of bacteria is treated with an antibiotic. Most of the bacteria die, but a few survive and reproduce. After many generations of continued treatment, nearly all of the bacteria in the population are resistant to the antibiotic. Which statement best explains this change?", options: ["A few bacteria already had a heritable resistance trait and passed it on", "Each bacterium became resistant because it needed to survive the drug", "The bacteria learned to resist the drug and taught this to offspring", "The antibiotic gave every bacterium it touched the same new resistance gene"], key: "A", basis: "Natural selection: pre-existing heritable variation plus differential survival and reproduction changes the frequency of the trait in the population; individuals do not acquire adaptations through need or learning." },
  { id: "science-912-07", subject: "science", band: "9-12", demand: "apply", strand: "chemistry", stem: "Carbon burns completely in oxygen according to the equation C + O2 -> CO2. What mass of carbon dioxide forms when 2.0 mol of carbon reacts completely? (Molar masses: C = 12 g/mol, O = 16 g/mol)", options: ["44 g", "56 g", "88 g", "24 g"], key: "C", basis: "computed: 1 mol C gives 1 mol CO2, so 2.0 mol CO2 forms; molar mass CO2 = 12 + 2(16) = 44 g/mol; 2.0 x 44 = 88 g. Distractors: 44 g = mass of only 1 mol, 56 g = used CO (28 g/mol), 24 g = mass of the carbon alone." },
  { id: "science-912-08", subject: "science", band: "9-12", demand: "apply", strand: "chemistry", stem: "A student dissolves 0.20 mol of sodium chloride in enough water to make 500 mL of solution. What is the concentration of the solution?", options: ["0.10 mol/L", "2.5 mol/L", "0.40 mol/L", "0.20 mol/L"], key: "C", basis: "computed: molarity = moles / liters = 0.20 mol / 0.500 L = 0.40 mol/L. Distractors: 0.10 = multiplied 0.20 x 0.500, 2.5 = inverted (0.500/0.20), 0.20 = ignored the volume." },
  { id: "science-912-09", subject: "science", band: "9-12", demand: "apply", strand: "chemistry", stem: "A sample of gas in a container with a movable piston has a volume of 2.0 L at 300 K. The gas is heated to 450 K while the pressure and the amount of gas stay constant. What is the new volume of the gas?", options: ["3.0 L", "1.3 L", "4.0 L", "2.0 L"], key: "A", basis: "computed: Charles's law, V1/T1 = V2/T2; V2 = 2.0 L x 450/300 = 3.0 L. Distractors: 1.3 L = inverse ratio (2.0 x 300/450), 4.0 L = assumed volume doubles, 2.0 L = assumed volume unchanged." },
  { id: "science-912-10", subject: "science", band: "9-12", demand: "apply", strand: "chemistry", stem: "Hydrochloric acid is a strong acid that ionizes completely in water. What is the pH of a 0.0010 mol/L solution of hydrochloric acid?", options: ["11", "-3", "1", "3"], key: "D", basis: "computed: [H+] = 1.0 x 10^-3 mol/L; pH = -log(10^-3) = 3. Distractors: 11 = pOH (14 - 3), -3 = dropped the negative sign in the definition, 1 = miscounted the decimal places." },
  { id: "science-912-11", subject: "science", band: "9-12", demand: "apply", strand: "chemistry", stem: "A particle has 17 protons, 20 neutrons and 18 electrons. What are its net charge and its mass number?", options: ["Charge 1+, mass number 37", "Charge 1-, mass number 37", "Charge 1-, mass number 35", "Charge 1+, mass number 35"], key: "B", basis: "computed: charge = protons - electrons = 17 - 18 = -1; mass number = protons + neutrons = 17 + 20 = 37. Distractors: sign of charge reversed; mass number from protons + electrons (35); both errors together." },
  { id: "science-912-12", subject: "science", band: "9-12", demand: "apply", strand: "chemistry", stem: "Propane burns according to the unbalanced equation C3H8 + O2 -> CO2 + H2O. When the equation is balanced using the smallest whole-number coefficients, what is the coefficient of O2?", options: ["5", "10", "4", "3"], key: "A", basis: "computed: C3H8 + 5 O2 -> 3 CO2 + 4 H2O; oxygen atoms on the right = 3(2) + 4(1) = 10, so 10/2 = 5 O2. Distractors: 10 = counted O atoms rather than O2 molecules, 4 = coefficient of H2O, 3 = coefficient of CO2." },
  { id: "science-912-13", subject: "science", band: "9-12", demand: "apply", strand: "physics", stem: "A 4.0 kg box is pushed across a level floor with a horizontal force of 20 N. A friction force of 8 N acts on the box in the opposite direction. What is the acceleration of the box?", options: ["3.0 m/s^2", "5.0 m/s^2", "7.0 m/s^2", "48 m/s^2"], key: "A", basis: "computed: Newton's second law, a = F_net/m = (20 N - 8 N)/4.0 kg = 12/4.0 = 3.0 m/s^2. Distractors: 5.0 = ignored friction (20/4), 7.0 = added friction (28/4), 48 = multiplied net force by mass." },
  { id: "science-912-14", subject: "science", band: "9-12", demand: "apply", strand: "physics", stem: "A car starts from rest and accelerates in a straight line at a constant 2.0 m/s^2 for 6.0 s. How far does the car travel during this time?", options: ["72 m", "36 m", "12 m", "6 m"], key: "B", basis: "computed: d = (1/2) a t^2 = 0.5 x 2.0 x 6.0^2 = 0.5 x 2.0 x 36 = 36 m. Distractors: 72 m = omitted the 1/2, 12 m = computed a x t (the final speed), 6 m = computed (1/2) a t without squaring." },
  { id: "science-912-15", subject: "science", band: "9-12", demand: "apply", strand: "physics", stem: "A 2.0 ohm resistor and a 4.0 ohm resistor are connected in series across a 12 V battery. What is the current in the circuit?", options: ["9.0 A", "2.0 A", "6.0 A", "3.0 A"], key: "B", basis: "computed: series resistance = 2.0 + 4.0 = 6.0 ohm; I = V/R = 12/6.0 = 2.0 A. Distractors: 9.0 A = treated as parallel (12/2 + 12/4), 6.0 A = used only the 2.0 ohm resistor, 3.0 A = used only the 4.0 ohm resistor." },
  { id: "science-912-16", subject: "science", band: "9-12", demand: "apply", strand: "physics", stem: "A wave on a rope has a frequency of 4.0 Hz and a wavelength of 2.0 m. What is the speed of the wave?", options: ["8.0 m/s", "2.0 m/s", "0.50 m/s", "6.0 m/s"], key: "A", basis: "computed: v = f x wavelength = 4.0 Hz x 2.0 m = 8.0 m/s. Distractors: 2.0 = frequency divided by wavelength, 0.50 = wavelength divided by frequency, 6.0 = added the two values." },
  { id: "science-912-17", subject: "science", band: "9-12", demand: "apply", strand: "physics", stem: "A 2.0 kg rock is dropped from rest from a ledge 20 m above the ground. Ignoring air resistance and using g = 10 m/s^2, what is the speed of the rock just before it reaches the ground?", options: ["400 m/s", "200 m/s", "14 m/s", "20 m/s"], key: "D", basis: "computed: conservation of energy, m g h = (1/2) m v^2, so v = sqrt(2 g h) = sqrt(2 x 10 x 20) = sqrt(400) = 20 m/s. Distractors: 400 = forgot the square root, 200 = computed g x h, 14 = sqrt(g h) without the factor of 2." },
  { id: "science-912-18", subject: "science", band: "9-12", demand: "apply", strand: "physics", stem: "A ball is thrown straight up and air resistance is negligible. Which statement describes the ball at the instant it reaches its highest point?", options: ["Its velocity is zero and its acceleration is also zero", "Its velocity is zero and its acceleration is 9.8 m/s^2 upward", "Its velocity is zero and its acceleration is 9.8 m/s^2 downward", "Its velocity is 9.8 m/s downward and its acceleration is zero"], key: "C", basis: "Kinematics of free fall: gravity is the only force throughout the flight, so acceleration is g downward at every instant, including the top where the velocity is momentarily zero." },
  { id: "science-912-19", subject: "science", band: "9-12", demand: "recall", strand: "earth/environment", stem: "What is the main cause of the yearly cycle of seasons at Earth's middle latitudes?", options: ["The change in Earth's distance from the Sun during its orbit", "The change in the Sun's energy output over the course of a year", "The change in the speed of Earth's rotation over the course of a year", "The tilt of Earth's axis relative to the plane of its orbit"], key: "D", basis: "Earth science: the 23.5 degree axial tilt changes the angle of sunlight and day length in each hemisphere through the year; Earth is actually closest to the Sun during the Northern Hemisphere winter." },
  { id: "science-912-20", subject: "science", band: "9-12", demand: "apply", strand: "earth/environment", stem: "Along the edge of a continent, geologists map a deep ocean trench just offshore and a line of explosive volcanoes on land that runs parallel to the coast. Strong earthquakes occur at increasing depths farther inland. Which setting best explains these features?", options: ["A divergent boundary where two plates are spreading apart", "A transform boundary where two plates slide past each other", "A convergent boundary where an oceanic plate sinks beneath the continent", "A hot spot located beneath the middle of a single plate"], key: "C", basis: "Plate tectonics: a trench, a parallel volcanic arc and an inclined zone of deepening earthquakes are the signature of subduction at an ocean-continent convergent boundary." },
  { id: "ela-k5-01", subject: "ela", band: "K-5", demand: "apply", strand: "parts of speech, grammar", stem: "Which word correctly completes the sentence? Yesterday, Mia ___ her bike to the park.", options: ["ride", "rided", "riding", "rode"], key: "D", basis: "The irregular past tense of 'ride' is 'rode'; 'Yesterday' signals simple past. 'ride' is present tense, 'rided' over-applies the -ed rule, and 'riding' needs a helping verb." },
  { id: "ela-k5-02", subject: "ela", band: "K-5", demand: "apply", strand: "parts of speech, grammar", stem: "Which word correctly completes the sentence? Three ___ ran across the kitchen floor.", options: ["mice", "mouses", "mouse", "mices"], key: "A", basis: "The irregular plural of 'mouse' is 'mice'. 'mouses' over-applies the -s rule, 'mouse' is singular, and 'mices' doubles the plural marking." },
  { id: "ela-k5-03", subject: "ela", band: "K-5", demand: "recall", strand: "parts of speech, grammar", stem: "What do we call a word that describes a noun, such as a word that tells its color or size?", options: ["adverb", "adjective", "verb", "pronoun"], key: "B", basis: "Standard grammar definition: an adjective modifies a noun or pronoun. An adverb modifies a verb, adjective or adverb; a verb shows action or being; a pronoun replaces a noun." },
  { id: "ela-k5-04", subject: "ela", band: "K-5", demand: "apply", strand: "parts of speech, grammar", stem: "Which choice correctly completes the sentence? My little brother ___ his teeth every night.", options: ["brushes", "brush", "brushing", "have brushed"], key: "A", basis: "Subject-verb agreement: the singular subject 'brother' takes the singular verb 'brushes'. 'brush' and 'have brushed' agree with a plural subject; 'brushing' lacks a helping verb." },
  { id: "ela-k5-05", subject: "ela", band: "K-5", demand: "apply", strand: "parts of speech, grammar", stem: "Which word correctly fills the blank? The twins forgot their coats, so the teacher handed the coats to ___.", options: ["them", "they", "their", "theirs"], key: "A", basis: "The object of the preposition 'to' takes the objective case pronoun 'them'. 'they' is subject case; 'their' and 'theirs' are possessive forms." },
  { id: "ela-k5-06", subject: "ela", band: "K-5", demand: "apply", strand: "parts of speech, grammar", stem: "Which choice correctly completes the sentence? Of the three puppies, the brown one is the ___.", options: ["smaller", "most small", "more smallest", "smallest"], key: "D", basis: "Comparing three or more things requires the superlative; one-syllable adjectives form it with -est, giving 'smallest'. 'smaller' compares only two, 'most small' uses the wrong superlative form for a one-syllable adjective, and 'more smallest' is a double comparison." },
  { id: "ela-k5-07", subject: "ela", band: "K-5", demand: "apply", strand: "spelling, punctuation", stem: "Which sentence is written with correct capitalization and end punctuation?", options: ["where did you put my shoes?", "Where did you put my shoes.", "Where did you put my shoes?", "Where did you put my Shoes?"], key: "C", basis: "A sentence begins with a capital letter, a question ends with a question mark, and a common noun such as 'shoes' is not capitalized. The distractors each break exactly one of these rules." },
  { id: "ela-k5-08", subject: "ela", band: "K-5", demand: "recall", strand: "spelling, punctuation", stem: "Which spelling correctly completes the sentence? My best ___ lives next door.", options: ["freind", "frend", "friend", "freand"], key: "C", basis: "Standard dictionary spelling is f-r-i-e-n-d. 'freind' reverses the i and e, 'frend' spells by sound, and 'freand' substitutes the ea vowel pattern." },
  { id: "ela-k5-09", subject: "ela", band: "K-5", demand: "apply", strand: "spelling, punctuation", stem: "Which sentence uses commas correctly?", options: ["We packed, apples cheese and crackers.", "We packed apples, cheese, and crackers.", "We packed apples cheese, and crackers.", "We packed apples, cheese, and, crackers."], key: "B", basis: "Commas separate the items in a series of three or more; the comma before the conjunction (the serial comma) is optional by style guide, and this is the only choice that punctuates the series without error. No comma belongs between the verb and its first object or after the word 'and'." },
  { id: "ela-k5-10", subject: "ela", band: "K-5", demand: "apply", strand: "spelling, punctuation", stem: "Two dogs share a basket of toys. Which phrase shows correctly that the toys belong to both dogs?", options: ["the dog's toys", "the dogs toys", "the dogs' toys", "the dogs's toys"], key: "C", basis: "A plural noun ending in s forms its possessive by adding only an apostrophe: dogs'. 'dog's' shows one dog as owner, 'dogs' with no apostrophe is a plain plural, and 'dogs's' adds an extra s." },
  { id: "ela-k5-11", subject: "ela", band: "K-5", demand: "recall", strand: "vocabulary", stem: "Which word means almost the same as the word enormous?", options: ["tiny", "noisy", "heavy", "huge"], key: "D", basis: "Dictionary definition: 'enormous' means very large, a synonym of 'huge'. 'tiny' is the antonym; 'noisy' and 'heavy' are qualities often associated with big things but are not the meaning." },
  { id: "ela-k5-12", subject: "ela", band: "K-5", demand: "apply", strand: "vocabulary", stem: "Read the sentence. The path was so narrow that the hikers had to walk one behind another. What does the word narrow mean in this sentence?", options: ["thin from side to side", "long from end to end", "steep and rocky", "dark and shady"], key: "A", basis: "Context clue: hikers could not walk side by side, so the path has little width. 'narrow' means having a small width; the sentence gives no clue about length, steepness or darkness." },
  { id: "ela-k5-13", subject: "ela", band: "K-5", demand: "recall", strand: "vocabulary", stem: "The prefix re- in the word rebuild has which meaning?", options: ["not", "again", "before", "under"], key: "B", basis: "The prefix re- means 'again' or 'back' (rebuild = build again). 'not' is the meaning of un-, 'before' is the meaning of pre-, and 'under' is the meaning of sub-." },
  { id: "ela-k5-14", subject: "ela", band: "K-5", demand: "apply", strand: "vocabulary", stem: "In which sentence does the word bat name an animal?", options: ["Luis swung the bat and hit the ball.", "A bat flew out of the cave at dusk.", "It will be your turn to bat next.", "She did not bat an eye at the news."], key: "B", basis: "'bat' is a multiple-meaning word. Only the sentence with the clues 'flew' and 'cave' uses the flying-mammal meaning; the others use the sports stick, the verb 'to hit', and the idiom meaning 'to blink'." },
  { id: "ela-k5-15", subject: "ela", band: "K-5", demand: "apply", strand: "vocabulary", stem: "Which word means the opposite of the word ancient?", options: ["aged", "fragile", "modern", "distant"], key: "C", basis: "Dictionary definition: 'ancient' means very old or from long ago; its antonym is 'modern', meaning of the present or recent times. 'aged' is a synonym; 'fragile' and 'distant' describe other qualities often linked with old things." },
  { id: "ela-k5-16", subject: "ela", band: "K-5", demand: "recall", strand: "comprehension", stem: "Read the passage. Nora planted bean seeds in a cup on Monday. She watered them every morning. By Friday, tiny green sprouts poked through the soil. What did Nora do every morning?", options: ["planted new seeds", "picked the sprouts", "gave the seeds water", "moved the cup outside"], key: "C", basis: "Stated directly in sentence 2 of the passage: 'She watered them every morning.' Planting happened only on Monday, and picking sprouts or moving the cup is never mentioned." },
  { id: "ela-k5-17", subject: "ela", band: "K-5", demand: "apply", strand: "comprehension", stem: "Read the passage. Jamal zipped his coat up to his chin and pulled his hat over his ears. His breath made little clouds in the air as he waited for the bus. What can the reader tell about the weather?", options: ["It is cold.", "It is rainy.", "It is hot.", "It is foggy."], key: "A", basis: "Inference from text evidence: a zipped coat, a hat over the ears, and visible breath all point to cold air. Nothing mentions rain or fog, and the 'clouds' are Jamal's breath, not weather." },
  { id: "ela-k5-18", subject: "ela", band: "K-5", demand: "apply", strand: "comprehension", stem: "Read the passage. Honeybees do many jobs in a hive. Some bees clean the cells, some feed the young, and others guard the entrance. Each bee's work helps the whole hive stay alive. What is the main idea of the passage?", options: ["Guard bees protect the hive door.", "Bees in a hive share different tasks.", "Honeybees make sweet honey.", "Young bees eat a lot of food."], key: "B", basis: "The first sentence states the topic (many jobs) and every other sentence supports it. The guard-bee choice is only one supporting detail, and honey-making and how much young bees eat are not stated in the passage." },
  { id: "ela-k5-19", subject: "ela", band: "K-5", demand: "apply", strand: "comprehension", stem: "Read the passage. The creek behind the school flooded after three days of heavy rain. Because the water covered the soccer field, the Saturday game was moved to the gym. Why was the game moved?", options: ["The gym had more seats.", "The school was closed for three days.", "The team forgot the soccer ball.", "The field was under water."], key: "D", basis: "Cause and effect signaled by 'Because' in sentence 2: the water covering the soccer field is the stated cause of the move. 'Three days' describes the rain, not a school closing, and seats and a ball are never mentioned." },
  { id: "ela-k5-20", subject: "ela", band: "K-5", demand: "apply", strand: "comprehension", stem: "Read the passage. Priya's tower of blocks fell for the fourth time. She took a deep breath, studied the wobbly base, and began stacking again with wider blocks at the bottom. Which word best describes Priya?", options: ["careless", "bored", "frightened", "determined"], key: "D", basis: "Character trait inferred from actions: after four failures Priya calms herself, studies the problem, and tries again with a better plan, which shows determination. Studying the base rules out careless, trying again rules out bored, and nothing suggests fear." },
  { id: "ela-68-01", subject: "ela", band: "6-8", demand: "apply", strand: "grammar, sentence structure", stem: "Which verb correctly completes the sentence? The box of old photographs ___ on the top shelf of the closet.", options: ["sits", "sit", "are sitting", "were sitting"], key: "A", basis: "Subject-verb agreement: the subject is the singular noun 'box' (not 'photographs,' which is the object of the preposition 'of'), so the verb must be singular: 'sits.'" },
  { id: "ela-68-02", subject: "ela", band: "6-8", demand: "apply", strand: "grammar, sentence structure", stem: "Read the sentence: Although the rain had stopped, the field was still too muddy for practice. What type of sentence is this?", options: ["a simple sentence", "a compound sentence", "a complex sentence", "a compound-complex sentence"], key: "C", basis: "Sentence structure rule: one dependent clause ('Although the rain had stopped') plus exactly one independent clause ('the field was still too muddy for practice') makes a complex sentence." },
  { id: "ela-68-03", subject: "ela", band: "6-8", demand: "apply", strand: "grammar, sentence structure", stem: "A student wrote this comma splice: Maya finished her essay, she forgot to add a title. Which revision corrects the error?", options: ["Maya finished her essay, but she forgot to add a title.", "Maya finished her essay she forgot to add a title.", "Maya finished her essay, however she forgot to add a title.", "Maya finished her essay. Forgetting to add a title."], key: "A", basis: "Two independent clauses may be joined by a comma plus a coordinating conjunction ('but'). Removing the comma creates a fused sentence; 'however' is a conjunctive adverb and needs a semicolon or period before it; 'Forgetting to add a title.' is a fragment." },
  { id: "ela-68-04", subject: "ela", band: "6-8", demand: "apply", strand: "grammar, sentence structure", stem: "Which pronoun correctly completes the sentence? The coach gave extra water to Devon and ___ after the long run.", options: ["me", "I", "myself", "we"], key: "A", basis: "Pronoun case: the pronoun is an object of the preposition 'to,' so the objective case is required ('to Devon and me'). 'I' and 'we' are subjective case; 'myself' is reflexive and needs 'I' as the subject of the clause." },
  { id: "ela-68-05", subject: "ela", band: "6-8", demand: "apply", strand: "grammar, sentence structure", stem: "In which sentence does the opening phrase clearly and correctly describe the person doing the running?", options: ["Running to catch the bus, Tomas's lunch dropped on the sidewalk.", "Running to catch the bus, the lunch slipped out of Tomas's hands.", "Running to catch the bus, the sidewalk was where Tomas dropped his lunch.", "Running to catch the bus, Tomas dropped his lunch on the sidewalk."], key: "D", basis: "Dangling modifier rule: an introductory participial phrase modifies the subject of the main clause. Only when the subject is 'Tomas' does the phrase describe the runner; in the others the subject is 'lunch' or 'sidewalk.'" },
  { id: "ela-68-06", subject: "ela", band: "6-8", demand: "apply", strand: "grammar, sentence structure", stem: "Which sentence is written in the active voice?", options: ["A new mascot was chosen by the committee last week.", "The committee chose a new mascot last week.", "The new mascot had been chosen before the meeting.", "The votes were being counted by two teachers."], key: "B", basis: "In active voice the subject performs the action ('The committee chose'). The other three use a form of 'be' plus a past participle with the subject receiving the action (passive voice)." },
  { id: "ela-68-07", subject: "ela", band: "6-8", demand: "recall", strand: "word roots, vocabulary", stem: "The Latin root aud, found in words such as audible and auditorium, has which meaning?", options: ["to see", "to speak", "to hear", "to gather"], key: "C", basis: "Latin audire means 'to hear'; audible = able to be heard, auditorium = a place for hearing. 'To see' is vid/vis, 'to speak' is dict/loqu, and 'to gather' confuses the root with what people do in an auditorium." },
  { id: "ela-68-08", subject: "ela", band: "6-8", demand: "apply", strand: "word roots, vocabulary", stem: "The prefix mal- means 'bad' or 'badly,' and the word function means 'to work.' Based on these word parts, a malfunctioning smoke alarm is one that", options: ["rings more loudly than other alarms", "does not operate the way it should", "has been switched off on purpose", "is being used for the very first time"], key: "B", basis: "mal- (badly) + function (work) = to work badly or fail to work properly." },
  { id: "ela-68-09", subject: "ela", band: "6-8", demand: "apply", strand: "word roots, vocabulary", stem: "Read the sentence: After two months without rain, the once-lush garden looked desolate, with cracked soil and bare stems where flowers used to grow. As used here, the word desolate most nearly means", options: ["damp and overgrown", "crowded and noisy", "empty and lifeless", "tidy and well kept"], key: "C", basis: "Context clues: 'without rain,' 'cracked soil,' 'bare stems,' and the contrast with 'once-lush' show the garden is barren; desolate means bleak, empty, and without life." },
  { id: "ela-68-10", subject: "ela", band: "6-8", demand: "apply", strand: "word roots, vocabulary", stem: "A reviewer says that a wristwatch on a knight in a movie about the Middle Ages is an anachronism. The word comes from Greek parts meaning 'against' or 'backward' (ana-) and 'time' (chron). An anachronism is", options: ["something placed in the wrong time period", "a mistake in measuring distance", "a story told in the correct order", "a person who records daily events"], key: "A", basis: "ana- (against) + chronos (time) = something out of its proper time; the wristwatch did not exist in the Middle Ages. Distractors confuse the word with chronological order and with a chronicler." },
  { id: "ela-68-11", subject: "ela", band: "6-8", demand: "apply", strand: "figurative language, literary terms", stem: "Read the sentence: Five minutes before the bell, the classroom was a beehive, with every table busy over the last details of its project. Which type of figurative language does the writer use when calling the classroom a beehive?", options: ["simile", "metaphor", "hyperbole", "onomatopoeia"], key: "B", basis: "A metaphor directly states that one thing is another unlike thing without using 'like' or 'as' (the classroom 'was a beehive'). A simile would require 'like' or 'as.'" },
  { id: "ela-68-12", subject: "ela", band: "6-8", demand: "apply", strand: "figurative language, literary terms", stem: "Read the sentence: \"I have told you a million times to latch the gate,\" Grandpa said as the goats wandered into the road again. The exaggeration in Grandpa's words mainly shows that he", options: ["has kept an exact count of his reminders", "is proud of how good his memory is", "thinks the open gate is a funny joke", "is frustrated at having to repeat himself"], key: "D", basis: "Hyperbole is deliberate exaggeration for emphasis, not a literal count; 'a million times' and 'again' emphasize his exasperation at repeating the reminder." },
  { id: "ela-68-13", subject: "ela", band: "6-8", demand: "recall", strand: "figurative language, literary terms", stem: "When an author plants hints or clues early in a story that suggest what will happen later, the author is using", options: ["flashback", "symbolism", "irony", "foreshadowing"], key: "D", basis: "Definition of the literary term foreshadowing: hints of events to come. A flashback interrupts the story to show earlier events; symbolism uses an object to stand for an idea; irony is a contrast between expectation and reality." },
  { id: "ela-68-14", subject: "ela", band: "6-8", demand: "apply", strand: "figurative language, literary terms", stem: "A swimming instructor known across the county for his water-safety lessons slips at his own award ceremony and has to be pulled out of a shallow wading pool by a six-year-old student. This event is best described as an example of", options: ["dramatic irony", "verbal irony", "situational irony", "understatement"], key: "C", basis: "Situational irony is when what happens is the opposite of what would be expected (a water-safety expert rescued by a small child). Dramatic irony requires the audience to know something a character does not; verbal irony is saying the opposite of what is meant." },
  { id: "ela-68-15", subject: "ela", band: "6-8", demand: "recall", strand: "figurative language, literary terms", stem: "A narrator who stands outside the story and can report the private thoughts and feelings of every character is telling the story from which point of view?", options: ["third-person limited", "first-person", "second-person", "third-person omniscient"], key: "D", basis: "Definition: an omniscient ('all-knowing') third-person narrator is not a character and has access to all characters' thoughts; a limited narrator follows only one character's thoughts." },
  { id: "ela-68-16", subject: "ela", band: "6-8", demand: "apply", strand: "inference on an ORIGINAL passage written inside the stem", stem: "Read the passage: Lena set her alarm for five o'clock, lined up her cleats by the front door, and filled two water bottles before bed. Then she read the tryout schedule one more time and taped it to her mirror. What can the reader best infer about Lena?", options: ["She is determined to be ready for the tryout.", "She expects the tryout to be canceled.", "She has never played the sport before.", "She was pushed into trying out by others."], key: "A", basis: "Inference from text evidence: setting an early alarm, preparing gear the night before, and rereading and posting the schedule all show careful, self-directed preparation; nothing in the passage supports cancellation, inexperience, or pressure from others." },
  { id: "ela-68-17", subject: "ela", band: "6-8", demand: "apply", strand: "inference on an ORIGINAL passage written inside the stem", stem: "Read the passage: When Mr. Okafor handed back the science tests, Jerome glanced at his paper, folded it twice, and pushed it to the bottom of his backpack. \"How did you do?\" asked Priya. \"Fine,\" he said, staring out the window. Which inference is best supported by the passage?", options: ["Jerome earned the best grade in the class.", "Jerome did not get his test back that day.", "Jerome believes Priya copied his answers.", "Jerome is unhappy with the score he received."], key: "D", basis: "Inference from text evidence: hiding the paper quickly, giving a one-word answer, and avoiding eye contact suggest disappointment he does not want to discuss. The passage states he did receive his paper and gives no evidence about cheating or a top grade." },
  { id: "ela-68-18", subject: "ela", band: "6-8", demand: "apply", strand: "inference on an ORIGINAL passage written inside the stem", stem: "Read the passage: Nadia tugged her scarf higher and watched her breath drift upward like smoke. The pond behind the barn had gone silent and hard, and the last of the geese had flown south many weeks ago. During which time of year does this scene most likely take place?", options: ["at the start of autumn", "at the end of summer", "in the middle of winter", "in the middle of spring"], key: "C", basis: "Inference from setting details: a scarf, visible breath, a frozen ('hard') pond, and geese that migrated south many weeks earlier point to deep winter rather than autumn, when the geese would just be leaving and the pond would not be frozen." },
  { id: "ela-68-19", subject: "ela", band: "6-8", demand: "apply", strand: "inference on an ORIGINAL passage written inside the stem", stem: "Read the passage: The bakery on Elm Street once had a line out the door every Saturday. Since the new highway opened and travelers stopped driving through the center of town, Mrs. Alvarez bakes half as many loaves and locks up at noon. What is the most likely reason the bakery now closes early?", options: ["Mrs. Alvarez has grown tired of baking bread.", "Fewer customers pass by the shop than before.", "The bread no longer tastes as good as it did.", "A rival bakery has opened on the same street."], key: "B", basis: "Cause-and-effect inference: the passage links the change to the highway opening and travelers no longer driving through town, which implies less customer traffic. No rival bakery, loss of quality, or loss of interest is mentioned." },
  { id: "ela-68-20", subject: "ela", band: "6-8", demand: "apply", strand: "inference on an ORIGINAL passage written inside the stem", stem: "Read the passage: Every afternoon, old Mr. Brandt complained loudly that the neighborhood children trampled his grass chasing their ball. Yet each morning, the ball that had rolled under his hedge the night before was waiting on the top step of his porch, wiped clean. What does the passage suggest about Mr. Brandt?", options: ["He plans to keep the ball as a punishment.", "He cares about the children more than he admits.", "He wants the children to move to another street.", "He has no idea who owns the ball in his yard."], key: "B", basis: "Inference from contrast between words and actions (signaled by 'Yet'): although he complains, he retrieves the ball, cleans it, and leaves it where the children can find it, showing hidden kindness. He returns rather than keeps the ball, and he clearly knows it belongs to the children." },
  { id: "ela-912-01", subject: "ela", band: "9-12", demand: "apply", strand: "usage and style", stem: "Read this sentence: Walking through the orchard at dawn, the fog hid the farthest rows of trees. Which revision corrects the dangling modifier?", options: ["Walking through the orchard at dawn, we lost sight of the farthest rows of trees in the fog.", "Walking through the orchard at dawn, the farthest rows of trees were hidden by the fog.", "The fog, walking through the orchard at dawn, hid the farthest rows of trees.", "Walking through the orchard at dawn, the fog's thickness hid the farthest rows of trees from us."], key: "A", basis: "Dangling-modifier rule: an introductory participial phrase must modify the subject of the main clause, and that subject must be the one performing the participle's action. Only 'we' can logically be walking through the orchard. The distractors make the walker 'the farthest rows of trees' (passive rewrite, still dangling), 'the fog' (modifier moved next to the wrong noun), or 'the fog's thickness' (walker mentioned only as an object, 'us', so the phrase still dangles)." },
  { id: "ela-912-02", subject: "ela", band: "9-12", demand: "apply", strand: "usage and style", stem: "Which sentence avoids an unclear pronoun reference?", options: ["When Priya handed Lena the report, she noticed a missing page.", "When Priya handed the report to Lena, Lena noticed a missing page.", "Priya told Lena that she had left out a page of the report.", "After Priya gave Lena the report, she said a page was missing."], key: "B", basis: "A pronoun needs one clear antecedent. In each distractor 'she' could refer to either Priya or Lena; the keyed sentence repeats the name, so no pronoun is left ambiguous." },
  { id: "ela-912-03", subject: "ela", band: "9-12", demand: "apply", strand: "usage and style", stem: "Which sentence is punctuated correctly?", options: ["The trail was steep, however, the view made the climb worthwhile.", "The trail was steep, however the view made the climb worthwhile.", "The trail was steep; however the view, made the climb worthwhile.", "The trail was steep; however, the view made the climb worthwhile."], key: "D", basis: "Two independent clauses joined by a conjunctive adverb take a semicolon before the adverb and a comma after it. Using only commas creates a comma splice, and a comma between subject and verb is an error." },
  { id: "ela-912-04", subject: "ela", band: "9-12", demand: "apply", strand: "usage and style", stem: "Choose the phrase that completes the sentence with parallel structure: The internship taught Marcus to manage his time, to write clear reports, and ___.", options: ["asking for help when he needed it", "to ask for help when he needed it", "he asked for help when he needed it", "that asking for help was something he needed"], key: "B", basis: "Parallelism: items in a series must share grammatical form. The first two items are infinitive phrases ('to manage', 'to write'), so the third must also be an infinitive phrase ('to ask')." },
  { id: "ela-912-05", subject: "ela", band: "9-12", demand: "apply", strand: "usage and style", stem: "Read the sentence: Due to the fact that the bridge was closed, the drivers made the decision to take a detour that was longer in length. Which revision is the most concise while remaining grammatically correct and keeping all of the original meaning?", options: ["The bridge was closed, the drivers took a detour.", "Because of the fact of the closed bridge, the drivers made a decision to detour for a longer length.", "Due to the bridge's closing being a fact, the drivers decided on taking a detour of longer length.", "Because the bridge was closed, the drivers took a longer detour."], key: "D", basis: "Concision: 'due to the fact that' reduces to 'because', 'made the decision to take' to 'took', and 'longer in length' to 'longer'. The shortest option is a comma splice and drops 'longer'; the other two keep the wordy constructions." },
  { id: "ela-912-06", subject: "ela", band: "9-12", demand: "apply", strand: "rhetoric, logical fallacies", stem: "A speaker at a town meeting says: Councilmember Ruiz wants us to repair the old footbridge, but she got two parking tickets last year, so her proposal can't be worth much. Which logical fallacy does the speaker commit?", options: ["straw man", "slippery slope", "false dilemma", "ad hominem"], key: "D", basis: "Ad hominem: the speaker rejects the proposal by attacking an irrelevant personal trait of the person making it (parking tickets) rather than addressing the merits of repairing the bridge. The proposal is not distorted, no chain of consequences is predicted, and no either/or choice is offered." },
  { id: "ela-912-07", subject: "ela", band: "9-12", demand: "apply", strand: "rhetoric, logical fallacies", stem: "A student writes: After the school installed new lights in the gym, the basketball team won six games in a row. The new lights clearly made the team better. Which fallacy weakens this reasoning?", options: ["circular reasoning", "post hoc (false cause)", "bandwagon appeal", "red herring"], key: "B", basis: "Post hoc ergo propter hoc: the writer assumes that because the winning streak followed the installation of the lights, the lights caused it, with no evidence of a causal link." },
  { id: "ela-912-08", subject: "ela", band: "9-12", demand: "apply", strand: "rhetoric, logical fallacies", stem: "A speech on bicycle safety begins: As a nurse who has worked in emergency rooms for twenty years, I have seen what happens when riders skip their helmets. The opening phrase about the speaker's career mainly builds which rhetorical appeal?", options: ["ethos, by establishing the speaker's credibility", "pathos, by stirring the audience's sympathy", "logos, by presenting statistical evidence", "kairos, by stressing the urgency of the moment"], key: "A", basis: "Classical rhetoric (Aristotle's appeals): ethos is the appeal to the speaker's character and authority. Citing twenty years of relevant professional experience establishes credibility; the phrase gives no statistics, emotional description, or reference to timing." },
  { id: "ela-912-09", subject: "ela", band: "9-12", demand: "apply", strand: "rhetoric, logical fallacies", stem: "Student A says: I think the cafeteria should offer one vegetarian entree each day. Student B replies: So you want to ban meat and force everyone to eat salad? That's ridiculous. Which statement best describes the flaw in Student B's reply?", options: ["It attacks Student A's character instead of addressing the proposal itself.", "It distorts Student A's claim into an extreme one that is easier to attack.", "It assumes one event caused another simply because it happened first.", "It restates its own conclusion as though that were evidence for it."], key: "B", basis: "Straw man fallacy: Student B replaces the modest proposal (one vegetarian option) with an exaggerated version (banning meat) and attacks that instead. Nothing is said about Student A's character, causation, or a self-supporting conclusion." },
  { id: "ela-912-10", subject: "ela", band: "9-12", demand: "apply", strand: "rhetoric, logical fallacies", stem: "Read this passage from an editorial: Admittedly, a later start time would complicate bus schedules. Yet the research on teenage sleep is too strong to ignore: rested students learn more. What is the rhetorical function of the first sentence?", options: ["the central claim that the rest of the passage supports with evidence", "an appeal to emotion meant to make readers pity the bus drivers", "a concession to an opposing view before the writer's rebuttal", "an anecdote drawn from the writer's own experience at school"], key: "C", basis: "Argument structure: 'Admittedly' signals a concession, in which the writer grants a point to the opposition; 'Yet' then introduces the rebuttal and the writer's actual claim about sleep research." },
  { id: "ela-912-11", subject: "ela", band: "9-12", demand: "apply", strand: "literary analysis of an original passage", stem: "Read the passage: The porch light had burned out weeks ago, and no one had replaced it. Inside, the clock in the hall ticked toward a time that nobody was keeping. Mara set her suitcase down on the same floorboard that had always creaked, and it creaked. The details in this passage most strongly create a mood of", options: ["cheerful anticipation", "sudden physical danger", "bitter, explosive anger", "quiet neglect and stillness"], key: "D", basis: "Mood is built from imagery and detail: an unreplaced bulb, a clock no one watches, and an unchanged creaking floorboard all suggest a hushed, neglected, unchanging house. No detail signals joy, threat, or rage." },
  { id: "ela-912-12", subject: "ela", band: "9-12", demand: "apply", strand: "literary analysis of an original passage", stem: "Read the passage: Mr. Hale had spent thirty years warning his students never to trust a shortcut. On the last day of school, a student found him at his desk, copying his farewell speech word for word from a greeting card. The passage is primarily an example of", options: ["situational irony", "dramatic irony", "verbal irony", "hyperbole"], key: "A", basis: "Situational irony is a contrast between what is expected and what actually happens: a teacher known for condemning shortcuts takes one himself. No character says the opposite of what he means (verbal irony), and the reader does not know something a character lacks (dramatic irony)." },
  { id: "ela-912-13", subject: "ela", band: "9-12", demand: "apply", strand: "literary analysis of an original passage", stem: "Read the passage: When the waiter brought the wrong order, Ines smiled, thanked him, and ate the soup she hadn't asked for. Later, alone in the car, she replayed the whole exchange aloud, this time giving herself the lines she had swallowed. The passage suggests that Ines", options: ["is truly indifferent to small mistakes and forgets them quickly", "avoids conflict in the moment but later regrets her silence", "takes pleasure in embarrassing workers who make careless errors", "feels proud of having spoken up firmly for what she wanted"], key: "B", basis: "Indirect characterization through action: she politely accepts the wrong order (avoiding conflict), then rehearses 'the lines she had swallowed' (words she held back), showing the incident bothered her and that she wishes she had spoken." },
  { id: "ela-912-14", subject: "ela", band: "9-12", demand: "apply", strand: "literary analysis of an original passage", stem: "Read the passage: Grandfather's memory was a house with the lights going out one room at a time. He still stood in the kitchen, bright and certain, describing the bread his mother baked in 1931, while the hallway to last Tuesday had gone dark. The extended metaphor suggests that the grandfather", options: ["is losing recent memories while older ones remain vivid", "is forgetting his childhood but recalls recent days clearly", "lives in a home that is falling into disrepair as he ages", "refuses to speak about painful events from his early life"], key: "A", basis: "In the metaphor, lit rooms are intact memories and dark rooms are lost ones. The 1931 kitchen is 'bright and certain' (old memory intact) while 'the hallway to last Tuesday' is dark (recent memory lost). The house is figurative, not literal." },
  { id: "ela-912-15", subject: "ela", band: "9-12", demand: "apply", strand: "literary analysis of an original passage", stem: "Read the passage: I told Owen the vase had been cracked when I found it, which was true in the way that a door is open if you are the one who opened it. He nodded. Owen always believes me; it is his least sensible quality. The narrator's comparison to the door most strongly implies that the narrator", options: ["found the vase already damaged by Owen", "is unsure how the vase came to be damaged", "hopes Owen will soon uncover the truth alone", "caused the damage and is concealing that fact"], key: "D", basis: "Inference from the analogy: a door is 'open' when you are the one who opened it, so the vase was 'cracked' because the narrator cracked it. The statement is technically true but misleading, and the remark that believing the narrator is not sensible confirms the deception." },
  { id: "ela-912-16", subject: "ela", band: "9-12", demand: "apply", strand: "literary analysis of an original passage", stem: "Read the passage: Every spring the river took a little more of the bank, and every spring Tobias drove new stakes and stacked new stones. His daughter asked why he bothered. 'Because it's ours,' he said, though by then the old stakes stood well out in the current, marking where the field used to be. Which theme does the passage most clearly develop?", options: ["Hard work always overcomes the forces of nature in the end.", "Children understand the land far better than their parents do.", "Devotion can persist even when the effort is bound to fail.", "People should give up any tradition that no longer earns a profit."], key: "C", basis: "Theme from textual evidence: the old stakes standing in the current show the river is winning year after year, yet Tobias keeps working out of attachment ('Because it's ours'). The passage shows nature prevailing, does not endorse the daughter's view, and makes no argument about profit." },
  { id: "ela-912-17", subject: "ela", band: "9-12", demand: "apply", strand: "vocabulary in context", stem: "Read the sentence: The committee's report was so terse that readers finished its two short paragraphs wishing for far more explanation. As used in the sentence, 'terse' most nearly means", options: ["harsh and insulting in tone", "confusing and poorly organized", "brief and sparing with words", "lengthy and full of repetition"], key: "C", basis: "Dictionary meaning of 'terse': using few words, concise to the point of abruptness. Context clues 'two short paragraphs' and 'wishing for far more explanation' confirm brevity rather than rudeness, disorder, or length." },
  { id: "ela-912-18", subject: "ela", band: "9-12", demand: "apply", strand: "vocabulary in context", stem: "Read the sentence: Although the principal's apology was politely worded, the students dismissed it as perfunctory, a gesture made only because the school board was watching. As used in the sentence, 'perfunctory' most nearly means", options: ["done as a routine duty, with little real care", "delivered with deep and obvious emotion", "offered much too late to make a difference", "expressed in unusually formal language"], key: "A", basis: "Dictionary meaning of 'perfunctory': carried out with minimal effort or reflection, merely to fulfill an obligation. The context clue 'made only because the school board was watching' signals an insincere, going-through-the-motions act." },
  { id: "ela-912-19", subject: "ela", band: "9-12", demand: "apply", strand: "vocabulary in context", stem: "Read the sentence: The drought will only compound the farmers' troubles, since their loans come due this fall. As used in the sentence, 'compound' most nearly means", options: ["combine two substances into one", "enclose within a fenced area", "make worse by adding to", "settle through mutual agreement"], key: "C", basis: "Multiple-meaning word: as a verb with an object like 'troubles', 'compound' means to intensify or add to an existing problem. The chemical sense, a verb gloss invented from the unrelated noun 'compound' (a fenced enclosure), and the legal sense (to settle) do not fit the context of a drought arriving on top of debts." },
  { id: "ela-912-20", subject: "ela", band: "9-12", demand: "apply", strand: "vocabulary in context", stem: "Read the sentence: Lena's ambivalence about the scholarship showed in the way she filled out the form eagerly one night and hid it in a drawer the next. As used in the sentence, 'ambivalence' most nearly means", options: ["a complete lack of interest", "steady and growing confidence", "mixed or conflicting feelings", "skill at doing two tasks equally well"], key: "C", basis: "Dictionary meaning of 'ambivalence': having simultaneous opposing attitudes toward something. The contrasting actions (eagerly filling out the form, then hiding it) show conflicting feelings, not apathy (indifference), confidence, or ambidexterity." },
  { id: "social-k5-01", subject: "social-studies", band: "K-5", demand: "recall", strand: "civics basics", stem: "Which branch of the United States government has the main job of making the nation's laws?", options: ["the executive branch", "the judicial branch", "the military branch", "the legislative branch"], key: "D", basis: "US Constitution, Art. I sec. 1: all legislative powers are vested in Congress, the legislative branch." },
  { id: "social-k5-02", subject: "social-studies", band: "K-5", demand: "apply", strand: "civics basics", stem: "A class votes on which game to play at recess. Kickball gets 14 votes and tag gets 9 votes, so the whole class plays kickball. Which idea about making group decisions does this show?", options: ["veto power", "majority rule", "checks and balances", "separation of powers"], key: "B", basis: "Majority rule means the choice with more than half of the votes wins; 14 of 23 votes is more than half." },
  { id: "social-k5-03", subject: "social-studies", band: "K-5", demand: "recall", strand: "civics basics", stem: "What name is given to the first ten amendments to the United States Constitution?", options: ["the Bill of Rights", "the Declaration of Independence", "the Articles of Confederation", "the Mayflower Compact"], key: "A", basis: "The first ten amendments to the US Constitution, ratified in 1791, are known as the Bill of Rights." },
  { id: "social-k5-04", subject: "social-studies", band: "K-5", demand: "apply", strand: "civics basics", stem: "A group of neighbors gathers calmly in a public park, holding signs that ask the city to fix a broken bridge. Which right protected by the First Amendment are they mainly using by meeting together?", options: ["freedom of religion", "freedom of assembly", "the right to a jury trial", "the right to vote"], key: "B", basis: "US Constitution, First Amendment: protects the right of the people peaceably to assemble; jury trial and voting are not First Amendment rights and religion is not involved." },
  { id: "social-k5-05", subject: "social-studies", band: "K-5", demand: "apply", strand: "civics basics", stem: "The lawmakers of a state pass a bill about school bus safety. Which official decides whether to sign that state bill into law or to veto it?", options: ["the president", "the mayor", "the governor", "the chief justice"], key: "C", basis: "In state governments the governor heads the executive branch and signs or vetoes bills passed by the state legislature; the president acts only on federal bills and a mayor on city matters." },
  { id: "social-k5-06", subject: "social-studies", band: "K-5", demand: "recall", strand: "geography, map skills (no figure needed)", stem: "Which imaginary line divides Earth into the Northern Hemisphere and the Southern Hemisphere?", options: ["the equator", "the prime meridian", "the Tropic of Cancer", "the International Date Line"], key: "A", basis: "The equator is the line of 0 degrees latitude, separating the Northern and Southern Hemispheres; the prime meridian separates east from west." },
  { id: "social-k5-07", subject: "social-studies", band: "K-5", demand: "apply", strand: "geography, map skills (no figure needed)", stem: "Lena stands facing north. She makes a quarter turn to her right. Which direction is she facing now?", options: ["west", "east", "south", "north"], key: "B", basis: "Cardinal directions go clockwise north, east, south, west; a quarter turn to the right (clockwise) from north is east. West is a turn to the left, south is a half turn, north is no turn." },
  { id: "social-k5-08", subject: "social-studies", band: "K-5", demand: "apply", strand: "geography, map skills (no figure needed)", stem: "A map's scale says that 1 inch stands for 50 miles. On the map, two towns are 3 inches apart. About how far apart are the real towns?", options: ["53 miles", "100 miles", "50 miles", "150 miles"], key: "D", basis: "Computed: 3 inches x 50 miles per inch = 150 miles. 53 comes from adding 50 + 3, 100 from using 2 inches, 50 from ignoring the map distance." },
  { id: "social-k5-09", subject: "social-studies", band: "K-5", demand: "recall", strand: "geography, map skills (no figure needed)", stem: "Which ocean is the largest on Earth?", options: ["the Atlantic Ocean", "the Indian Ocean", "the Pacific Ocean", "the Arctic Ocean"], key: "C", basis: "The Pacific Ocean is the largest and deepest of Earth's oceans, covering roughly one third of the planet's surface." },
  { id: "social-k5-10", subject: "social-studies", band: "K-5", demand: "apply", strand: "geography, map skills (no figure needed)", stem: "Marcus wants to find the borders between states and the location of each state's capital city. Which kind of map would help him most?", options: ["a physical map", "a political map", "a climate map", "a population map"], key: "B", basis: "Political maps show human-made boundaries such as state and national borders and mark capitals and cities; physical maps show landforms, climate maps show weather patterns, population maps show where people live." },
  { id: "social-k5-11", subject: "social-studies", band: "K-5", demand: "apply", strand: "geography, map skills (no figure needed)", stem: "A city is located at 40 degrees N latitude and 75 degrees W longitude. In which two hemispheres is the city found?", options: ["Northern and Western", "Northern and Eastern", "Southern and Western", "Southern and Eastern"], key: "A", basis: "Latitude marked N is north of the equator (Northern Hemisphere); longitude marked W is west of the prime meridian (Western Hemisphere)." },
  { id: "social-k5-12", subject: "social-studies", band: "K-5", demand: "recall", strand: "US history basics", stem: "Who was the main writer of the Declaration of Independence?", options: ["George Washington", "Benjamin Franklin", "Abraham Lincoln", "Thomas Jefferson"], key: "D", basis: "Thomas Jefferson drafted the Declaration of Independence in June 1776 for the Continental Congress's committee of five." },
  { id: "social-k5-13", subject: "social-studies", band: "K-5", demand: "recall", strand: "US history basics", stem: "What was the main reason the Pilgrims sailed to North America on the Mayflower in 1620?", options: ["to search for gold and silver", "to worship in their own way", "to escape a tax on tea", "to find a water route to Asia"], key: "B", basis: "The Pilgrims were Separatists who left England to worship outside the Church of England, lived for about twelve years in the Netherlands, and then sailed in 1620 to found Plymouth Colony, where they could keep their own church and community." },
  { id: "social-k5-14", subject: "social-studies", band: "K-5", demand: "apply", strand: "US history basics", stem: "A student is putting four events on a timeline of American history. Which of these events should be placed earliest?", options: ["the founding of Jamestown", "the Boston Tea Party", "the Louisiana Purchase", "the California Gold Rush"], key: "A", basis: "Jamestown was founded in 1607; the Boston Tea Party was 1773, the Louisiana Purchase 1803, and the California Gold Rush began in 1848." },
  { id: "social-k5-15", subject: "social-studies", band: "K-5", demand: "apply", strand: "US history basics", stem: "Ana is studying what life was like for families traveling west on the Oregon Trail in the 1840s. Which of these would be a primary source for her project?", options: ["a diary a traveler kept on the trail", "a chapter in her history textbook", "a new movie about the pioneers", "an encyclopedia article on the trail"], key: "A", basis: "A primary source is created by someone who took part in or witnessed the event at the time; a traveler's diary qualifies, while textbooks, later films and encyclopedias are secondary sources." },
  { id: "social-k5-16", subject: "social-studies", band: "K-5", demand: "recall", strand: "US history basics", stem: "Before the American Revolution, many colonists were angry with the British government. Which complaint was one of their main reasons?", options: ["They were forced to move west of the mountains.", "They were not allowed to grow their own food.", "They were stopped from trading with Britain.", "They were taxed without a voice in Parliament."], key: "D", basis: "Colonial protests against the Stamp Act (1765) and later taxes centered on 'no taxation without representation' because colonists elected no members of Parliament." },
  { id: "social-k5-17", subject: "social-studies", band: "K-5", demand: "apply", strand: "economics basics", stem: "Sam has enough money to buy only one thing: a comic book or a kite. He decides to buy the comic book. What is Sam's opportunity cost?", options: ["the comic book he bought", "the price tag on the comic book", "the kite he gave up", "the store where he shopped"], key: "C", basis: "Opportunity cost is the next best alternative given up when a choice is made; Sam's only other choice was the kite." },
  { id: "social-k5-18", subject: "social-studies", band: "K-5", demand: "recall", strand: "economics basics", stem: "In economics, goods are things you can touch and services are jobs people do for others. Which of these is a service?", options: ["a loaf of bread", "a pair of sneakers", "a new bicycle", "a haircut from a barber"], key: "D", basis: "A service is work done for someone else; a haircut is an action performed by a barber, while bread, sneakers and a bicycle are physical goods." },
  { id: "social-k5-19", subject: "social-studies", band: "K-5", demand: "apply", strand: "economics basics", stem: "A hard frost destroys most of the orange crop, so stores have far fewer oranges to sell. Just as many people still want to buy oranges. What will most likely happen to the price of oranges?", options: ["It will go down.", "It will stay the same.", "It will go up.", "It will drop to zero."], key: "C", basis: "Law of supply and demand: when supply falls and demand stays the same, the good becomes scarcer and its price rises." },
  { id: "social-k5-20", subject: "social-studies", band: "K-5", demand: "recall", strand: "economics basics", stem: "What do economists call a person who buys and uses goods and services?", options: ["a producer", "a seller", "a consumer", "an investor"], key: "C", basis: "Standard economics definition: a consumer is someone who purchases and uses goods and services; producers and sellers make or supply them." },
  { id: "social-68-01", subject: "social-studies", band: "6-8", demand: "recall", strand: "world history to 1450", stem: "The earliest cities of Mesopotamia grew up in the land between which two rivers?", options: ["The Nile and the Niger", "The Tigris and the Euphrates", "The Indus and the Ganges", "The Huang He and the Yangtze"], key: "B", basis: "Mesopotamia ('land between the rivers') lies between the Tigris and Euphrates in present-day Iraq; the other pairs belong to Africa, South Asia and China." },
  { id: "social-68-02", subject: "social-studies", band: "6-8", demand: "apply", strand: "world history to 1450", stem: "A village in an early river valley begins growing much more grain than its people need to eat. Which change is most likely to follow?", options: ["The villagers give up their fields and return to hunting and gathering for food", "The villagers abandon permanent homes and begin following herds of wild animals", "Some villagers stop farming and take up specialized jobs such as pottery or metalworking", "The village breaks apart because people no longer have any reason to live together"], key: "C", basis: "Food surpluses in early agricultural societies freed part of the population from farming, leading to division of labor and specialization, a standard feature of early civilizations." },
  { id: "social-68-03", subject: "social-studies", band: "6-8", demand: "recall", strand: "world history to 1450", stem: "Why is the law code of Hammurabi, a king of Babylon, considered important in world history?", options: ["It gave every person the same punishment regardless of social class", "It created the first government in which citizens voted on the laws", "It was a written set of laws displayed so that people could know the rules", "It ended the practice of slavery throughout the cities of Mesopotamia"], key: "C", basis: "Hammurabi's Code (c. 1750s BCE) is one of the earliest known written law codes, inscribed on stone pillars for public display; its punishments varied by social class, it did not involve voting, and it regulated rather than ended slavery." },
  { id: "social-68-04", subject: "social-studies", band: "6-8", demand: "apply", strand: "world history to 1450", stem: "In ancient Athens, citizens met in an assembly and voted on laws themselves. In the Roman Republic, citizens elected officials who then made many decisions for them. Which pair of terms best describes these two systems, in that order?", options: ["Representative government; direct democracy", "Absolute monarchy; direct democracy", "Direct democracy; representative government", "Direct democracy; absolute monarchy"], key: "C", basis: "Citizens voting on laws themselves defines direct democracy (Athens); electing officials to decide defines representative (republican) government (Rome)." },
  { id: "social-68-05", subject: "social-studies", band: "6-8", demand: "recall", strand: "world history to 1450", stem: "Which of these was a result of trade and travel along the Silk Road?", options: ["Maize and potatoes spread from the Americas into Asia", "Rome and Han China formed a military alliance", "Printing with metal type spread from Germany into China", "Buddhism spread from India into China"], key: "D", basis: "Buddhist monks and merchants carried Buddhism from India through Central Asia into China along Silk Road routes during and after the Han dynasty; American crops came only after 1492, Rome and Han China never allied, and printing originated in East Asia." },
  { id: "social-68-06", subject: "social-studies", band: "6-8", demand: "apply", strand: "world history to 1450", stem: "The Black Death killed a large share of Europe's population in the 1300s. What was the most likely effect on the peasants and laborers who survived?", options: ["They earned lower wages because there was less land left to farm", "They could demand higher wages because workers had become scarce", "They lost their jobs because towns no longer needed any goods", "They were required to pay higher rents because land had become scarce"], key: "B", basis: "With far fewer workers and the same amount of land, labor became scarce and its price rose; historians document rising wages and weakening serfdom in western Europe after the plague. Land became more plentiful per person, not scarcer." },
  { id: "social-68-07", subject: "social-studies", band: "6-8", demand: "recall", strand: "US history to 1877", stem: "Why did many American colonists object to the Stamp Act of 1765?", options: ["They had no elected representatives in the Parliament that passed the tax", "It required them to house British soldiers in their private homes", "It banned them from printing newspapers and legal documents", "It closed the lands west of the Appalachian Mountains to settlement"], key: "A", basis: "Colonial protests against the Stamp Act centered on 'no taxation without representation' (Stamp Act Congress resolutions, 1765). The distractors confuse it with the Quartering Act, a ban rather than a tax, and the Proclamation of 1763." },
  { id: "social-68-08", subject: "social-studies", band: "6-8", demand: "apply", strand: "US history to 1877", stem: "Under the Articles of Confederation, Congress asked the states for money to pay war debts, and several states simply did not pay. Which weakness of the Articles does this situation show?", options: ["Congress had no power to collect taxes", "Congress had no power to declare war", "The president could veto spending bills", "National courts always sided with the states"], key: "A", basis: "Under the Articles of Confederation, Congress could only request funds from states and could not levy taxes. The Articles did allow Congress to declare war, and they created no president and no national court system." },
  { id: "social-68-09", subject: "social-studies", band: "6-8", demand: "recall", strand: "US history to 1877", stem: "What was a major effect of the Louisiana Purchase of 1803?", options: ["It transferred Florida from Spain to the United States", "It roughly doubled the land area of the United States", "It ended a war between the United States and Britain", "It added California to the United States after a war"], key: "B", basis: "The 1803 purchase of the Louisiana Territory from France added about 828,000 square miles, roughly doubling the nation's size. Florida came by the Adams-Onis Treaty (1819), and California by the Mexican Cession (1848)." },
  { id: "social-68-10", subject: "social-studies", band: "6-8", demand: "apply", strand: "US history to 1877", stem: "In 1820, Congress agreed to admit Missouri as a slave state and Maine as a free state at about the same time. What was the main purpose of admitting them together?", options: ["To let the settlers of each new territory vote on whether to allow slavery", "To begin ending slavery gradually in all lands west of the Mississippi", "To keep the number of free states and slave states equal in the Senate", "To give the free states a lasting majority in the House of Representatives"], key: "C", basis: "The Missouri Compromise (1820) paired Missouri and Maine to keep free and slave states equal (11 each before, 12 each after), and thus equal votes in the Senate. Letting settlers vote (popular sovereignty) came later with the Kansas-Nebraska Act." },
  { id: "social-68-11", subject: "social-studies", band: "6-8", demand: "recall", strand: "US history to 1877", stem: "Which enslaved people did the Emancipation Proclamation of 1863 declare to be free?", options: ["All enslaved people everywhere in the United States", "Those in the border states that had stayed in the Union", "Those in Union states who agreed to join the army", "Those in Confederate areas still in rebellion against the Union"], key: "D", basis: "The Emancipation Proclamation (January 1, 1863) applied only to areas in rebellion; it did not cover the loyal border states and exempted Tennessee and specified Union-occupied parts of Louisiana and Virginia. Slavery was abolished nationwide by the Thirteenth Amendment (1865)." },
  { id: "social-68-12", subject: "social-studies", band: "6-8", demand: "apply", strand: "US history to 1877", stem: "In 1871, a formerly enslaved man in a Southern state casts a ballot in a national election. Which constitutional amendment most directly protected his right to do so?", options: ["The Thirteenth Amendment", "The Fifteenth Amendment", "The Fourteenth Amendment", "The Nineteenth Amendment"], key: "B", basis: "US Constitution, Amendment XV (1870): the right to vote shall not be denied on account of race, color, or previous condition of servitude. The Thirteenth abolished slavery, the Fourteenth defined citizenship and equal protection, the Nineteenth concerned women's suffrage." },
  { id: "social-68-13", subject: "social-studies", band: "6-8", demand: "recall", strand: "US Constitution, branches of government", stem: "Congress passes a bill, and the president vetoes it. According to the Constitution, how can the bill still become a law?", options: ["A simple majority of the Senate votes to override the veto", "Three-fourths of the state legislatures vote to approve the bill", "The Supreme Court votes that the president's veto was unwise", "Two-thirds of each house of Congress votes to override the veto"], key: "D", basis: "US Constitution, Art. I, sec. 7: a vetoed bill becomes law if repassed by two-thirds of both houses. Three-fourths of the states is the ratification rule for amendments (Art. V)." },
  { id: "social-68-14", subject: "social-studies", band: "6-8", demand: "apply", strand: "US Constitution, branches of government", stem: "A federal court rules that a law passed by Congress and signed by the president violates the Constitution and can no longer be enforced. Which power is the court using?", options: ["Judicial review", "Impeachment", "The veto power", "Federalism"], key: "A", basis: "Judicial review, established in Marbury v. Madison (1803), is the power of courts to declare laws unconstitutional. Impeachment belongs to Congress, the veto to the president, and federalism is the division of power between national and state governments." },
  { id: "social-68-15", subject: "social-studies", band: "6-8", demand: "apply", strand: "US Constitution, branches of government", stem: "State X has ten times as many people as State Y. How does this difference affect their representation in Congress?", options: ["State X has more senators, but the two states have equal numbers of House members", "State X has more members than State Y in both the House and the Senate", "State X and State Y have equal numbers of members in both the House and Senate", "State X has more House members, but the two states have equal numbers of senators"], key: "D", basis: "US Constitution, Art. I, sec. 2 (House seats apportioned by population) and Art. I, sec. 3 with Amendment XVII (two senators per state)." },
  { id: "social-68-16", subject: "social-studies", band: "6-8", demand: "recall", strand: "US Constitution, branches of government", stem: "Which right is protected by the First Amendment to the Constitution?", options: ["The right to a speedy and public trial by jury", "The protection against unreasonable searches", "The right of the people to keep and bear arms", "The freedom to practice a religion of one's choice"], key: "D", basis: "US Constitution, Amendment I: protects free exercise of religion, speech, press, assembly and petition. The distractors are from Amendments VI, IV and II." },
  { id: "social-68-17", subject: "social-studies", band: "6-8", demand: "apply", strand: "geography", stem: "City A lies at 5 degrees north latitude and City B lies at 60 degrees north latitude. Both are on the coast at sea level. Which statement is most likely true?", options: ["City B is warmer over the year because higher latitudes get more sunlight", "City A is warmer over the year because it receives more direct sunlight", "The cities have about the same temperatures because both are on the coast", "City A has much colder winters because it is closer to the equator"], key: "B", basis: "Low latitudes near the equator receive more direct solar radiation year-round, so average temperatures fall as latitude increases, holding elevation and coastal location constant." },
  { id: "social-68-18", subject: "social-studies", band: "6-8", demand: "recall", strand: "geography", stem: "Which term names a narrow strip of land that connects two larger landmasses and has water on both sides?", options: ["Peninsula", "Strait", "Isthmus", "Archipelago"], key: "C", basis: "Standard physical geography definition: an isthmus is a narrow land bridge joining two larger land areas. A peninsula is land surrounded by water on three sides, a strait is a narrow water passage, and an archipelago is a group of islands." },
  { id: "social-68-19", subject: "social-studies", band: "6-8", demand: "apply", strand: "geography", stem: "On a map, the scale says that 1 centimeter represents 50 kilometers. Two cities are 7 centimeters apart on the map. About how far apart are the cities in real life?", options: ["350 kilometers", "57 kilometers", "35 kilometers", "3,500 kilometers"], key: "A", basis: "computed: 7 cm x 50 km per cm = 350 km. Distractors: 57 = 50 + 7 (added); 35 and 3,500 = place-value slips either side." },
  { id: "social-68-20", subject: "social-studies", band: "6-8", demand: "apply", strand: "geography", stem: "Moist winds blow from the ocean toward the east and rise over a tall mountain range that runs north to south. Which area is likely to be the driest?", options: ["The land just east of the mountains", "The slopes on the western side of the range", "The coastline west of the mountains", "The highest peaks of the mountain range"], key: "A", basis: "Rain shadow effect: air rising on the windward (here western) side cools and drops its moisture; descending air on the leeward (eastern) side is dry, producing arid conditions there." },
  { id: "social-912-01", subject: "social-studies", band: "9-12", demand: "recall", strand: "US history 1877-1991", stem: "In 1887 Congress responded to complaints from farmers and small shippers about unfair railroad rates by passing a law that created the first federal regulatory commission. Which law was this?", options: ["Sherman Antitrust Act", "Interstate Commerce Act", "Pendleton Civil Service Act", "Homestead Act"], key: "B", basis: "The Interstate Commerce Act of 1887 created the Interstate Commerce Commission to regulate railroad rates; the Sherman Act (1890) targeted trusts, the Pendleton Act (1883) reformed federal hiring, and the Homestead Act (1862) distributed western land." },
  { id: "social-912-02", subject: "social-studies", band: "9-12", demand: "apply", strand: "US history 1877-1991", stem: "In 1904 a magazine writer publishes a carefully documented series of articles revealing how a large oil company used secret railroad rebates to drive its competitors out of business. The series leads readers to demand government action. Historians would most accurately describe this writer as a", options: ["muckraker", "carpetbagger", "robber baron", "nativist"], key: "A", basis: "Muckrakers were Progressive Era investigative journalists who exposed corporate and political abuses to prompt reform; carpetbaggers were Northerners who moved South during Reconstruction, robber barons were the industrialists being criticized, and nativists opposed immigration." },
  { id: "social-912-03", subject: "social-studies", band: "9-12", demand: "apply", strand: "US history 1877-1991", stem: "In 1942 a 67-year-old retired factory worker receives a monthly check from the federal government. The payments are funded by a payroll tax that had been collected from workers and their employers. Which New Deal measure created this program?", options: ["Social Security Act", "Agricultural Adjustment Act", "Civilian Conservation Corps", "Works Progress Administration"], key: "A", basis: "The Social Security Act of 1935 established old-age pensions financed by payroll taxes on workers and employers; the AAA paid farmers to limit production, and the CCC and WPA were work-relief jobs programs, not retirement pensions." },
  { id: "social-912-04", subject: "social-studies", band: "9-12", demand: "apply", strand: "US history 1877-1991", stem: "In 1947 President Truman asked Congress for military and economic aid for Greece and Turkey so that those countries could resist communist pressure. The goal was to keep Soviet influence from spreading beyond where it already existed. This request is an example of which foreign policy?", options: ["isolationism", "appeasement", "detente", "containment"], key: "D", basis: "The Truman Doctrine (1947) was the first major application of containment, the policy of preventing the further spread of communism; isolationism avoids foreign commitments, appeasement gives in to an aggressor's demands, and detente was the 1970s easing of Cold War tensions." },
  { id: "social-912-05", subject: "social-studies", band: "9-12", demand: "recall", strand: "US history 1877-1991", stem: "Which statement best describes a major effect of the Voting Rights Act of 1965?", options: ["It outlawed segregation in hotels, restaurants and other public accommodations", "It declared racially segregated public schools to be unconstitutional", "It ended the use of poll taxes in elections for federal offices", "It suspended literacy tests and allowed federal oversight of voter registration"], key: "D", basis: "The Voting Rights Act of 1965 suspended literacy tests and authorized federal examiners to oversee registration in covered areas; public accommodations were addressed by the Civil Rights Act of 1964, school segregation by Brown v. Board of Education (1954), and federal poll taxes by the 24th Amendment (1964)." },
  { id: "social-912-06", subject: "social-studies", band: "9-12", demand: "apply", strand: "world history 1450-1991", stem: "After 1492, crops such as potatoes and maize were carried from the Americas to Europe, where farmers found they produced large amounts of food on small plots of land. Which long-term effect did these crops most likely have in Europe?", options: ["Population collapsed as unfamiliar diseases spread through the continent", "Overseas trade declined as European countries became self-sufficient", "Feudal lords regained power as peasants returned to manors", "Population grew as the food supply became larger and more reliable"], key: "D", basis: "A well-established effect of the Columbian Exchange is that high-yield American crops such as the potato and maize supported European population growth; the disease-driven population collapse occurred among Indigenous peoples of the Americas, and overseas trade expanded rather than declined." },
  { id: "social-912-07", subject: "social-studies", band: "9-12", demand: "recall", strand: "world history 1450-1991", stem: "Which Enlightenment thinker argued that liberty is best protected when the legislative, executive and judicial functions of government are placed in separate bodies?", options: ["Thomas Hobbes", "Baron de Montesquieu", "Jean-Jacques Rousseau", "Adam Smith"], key: "B", basis: "Montesquieu, The Spirit of the Laws (1748), set out the doctrine of separation of powers; Hobbes defended a strong sovereign, Rousseau emphasized the general will and popular sovereignty, and Smith wrote on market economics." },
  { id: "social-912-08", subject: "social-studies", band: "9-12", demand: "recall", strand: "world history 1450-1991", stem: "A historian is explaining why the Industrial Revolution began in Great Britain in the late 1700s rather than elsewhere. Which condition would the historian most likely cite?", options: ["Large deposits of coal and iron and wealth available to invest", "A large population of serfs legally bound to noble estates", "Government ownership of nearly all mines and workshops", "A policy of closing ports to foreign goods and merchants"], key: "A", basis: "Standard explanations for Britain's early industrialization include abundant coal and iron, available investment capital, a mobile labor force and extensive trade; Britain had no serfdom in this period, its industry was privately owned, and it traded widely overseas." },
  { id: "social-912-09", subject: "social-studies", band: "9-12", demand: "apply", strand: "world history 1450-1991", stem: "In the summer of 1914 a dispute between Austria-Hungary and Serbia followed the assassination of an Austrian archduke. Within weeks Russia, Germany, France and Great Britain had all entered the conflict. Which factor best explains why a regional dispute spread so quickly?", options: ["A set of harsh reparations payments that had been imposed on Germany", "A system of military alliances that committed the great powers to defend one another", "A worldwide economic depression that had caused mass unemployment", "A wave of communist revolutions that had overthrown several monarchies"], key: "B", basis: "The Triple Alliance and Triple Entente alliance systems drew the great powers into war in 1914; reparations came from the 1919 Treaty of Versailles, the global depression began in 1929, and the Russian Revolution occurred in 1917, all after the war began." },
  { id: "social-912-10", subject: "social-studies", band: "9-12", demand: "apply", strand: "world history 1450-1991", stem: "In 1930 thousands of people in British-ruled India walked to the seacoast and made their own salt, openly breaking a law that required them to buy taxed salt from the colonial government. They did not fight back when arrested. This protest is best described as an example of", options: ["guerrilla warfare", "economic imperialism", "civil disobedience", "collectivization"], key: "C", basis: "Gandhi's Salt March (1930) was a campaign of nonviolent civil disobedience, the deliberate and peaceful breaking of a law considered unjust; guerrilla warfare is armed resistance, economic imperialism describes the colonizer's control, and collectivization was the Soviet merging of farms." },
  { id: "social-912-11", subject: "social-studies", band: "9-12", demand: "recall", strand: "US government", stem: "Under the US Constitution, after a federal official has been impeached, which body holds the trial to decide whether that official is removed from office?", options: ["the Senate", "the House of Representatives", "the Supreme Court", "the Cabinet"], key: "A", basis: "US Constitution, Art. I sec. 3: the Senate has the sole power to try all impeachments; the House has the sole power to impeach (Art. I sec. 2)." },
  { id: "social-912-12", subject: "social-studies", band: "9-12", demand: "apply", strand: "US government", stem: "Congress passes a bill, but the president vetoes it and sends it back with objections. Supporters of the bill still want it to become law without the president's signature. What must happen?", options: ["A simple majority in each house must approve it again", "Two-thirds of the members voting in each house must approve it again", "Three-fourths of the state legislatures must ratify it", "Two-thirds of the Senate alone must approve it again"], key: "B", basis: "US Constitution, Art. I sec. 7: a vetoed bill becomes law if two-thirds of each house votes to override; three-fourths of the states is the ratification requirement for amendments (Art. V), and a Senate-only two-thirds vote applies to treaties." },
  { id: "social-912-13", subject: "social-studies", band: "9-12", demand: "apply", strand: "US government", stem: "A worker pays an income tax to the national government and also pays a separate income tax to the government of the state where she lives. Because both levels of government may collect taxes at the same time, the power to tax is classified as a", options: ["concurrent power", "reserved power", "implied power", "inherent power"], key: "A", basis: "In US federalism, concurrent powers are those exercised by both the national and state governments, such as taxing, borrowing and establishing courts; reserved powers belong only to the states (10th Amendment), and implied powers derive from the Necessary and Proper Clause." },
  { id: "social-912-14", subject: "social-studies", band: "9-12", demand: "apply", strand: "US government", stem: "Police officers enter a person's home and look through closets and drawers. They have no warrant, no permission from the resident, and no emergency. At trial the judge refuses to allow the items they found to be used as evidence. The judge's decision is based most directly on which amendment?", options: ["Fifth Amendment", "Sixth Amendment", "Eighth Amendment", "Fourth Amendment"], key: "D", basis: "US Constitution, Fourth Amendment: protection against unreasonable searches and seizures and the warrant requirement; the Fifth covers self-incrimination and due process, the Sixth covers trial rights, and the Eighth covers bail and punishments." },
  { id: "social-912-15", subject: "social-studies", band: "9-12", demand: "apply", strand: "US government", stem: "Congress passes a law and the president signs it. Later, in deciding a case, the Supreme Court rules that the law conflicts with the Constitution and therefore cannot be enforced. Which power is the Court using?", options: ["executive privilege", "judicial review", "legislative oversight", "original jurisdiction"], key: "B", basis: "Judicial review, established in Marbury v. Madison (1803), is the power of courts to declare acts of the other branches unconstitutional; executive privilege belongs to the president, oversight belongs to Congress, and original jurisdiction refers to which court hears a case first." },
  { id: "social-912-16", subject: "social-studies", band: "9-12", demand: "apply", strand: "economics", stem: "In a small country, 190 thousand people have jobs, 10 thousand people have no job but are actively looking for one, and 50 thousand adults have no job and are not looking for one. What is the unemployment rate?", options: ["4.0%", "5.3%", "24.0%", "5.0%"], key: "D", basis: "computed: labor force = employed + unemployed = 190 + 10 = 200 thousand; unemployment rate = 10 / 200 = 0.05 = 5.0%. Distractors: 10/250 = 4.0% (wrongly includes people not in the labor force in the denominator); 10/190 = 5.3% (divides by employed only); 60/250 = 24.0% (counts everyone without a job)." },
  { id: "social-912-17", subject: "social-studies", band: "9-12", demand: "apply", strand: "economics", stem: "A bakery raises the price of a loaf of bread from $4 to $5, and the number of loaves sold each day falls from 100 to 80. Using simple percentage changes measured from the original price and the original quantity, what is the price elasticity of demand (as a positive number)?", options: ["1.25", "0.20", "0.80", "20.00"], key: "C", basis: "computed: % change in quantity = (80 - 100)/100 = -20%; % change in price = (5 - 4)/4 = 25%; elasticity = 20/25 = 0.80 in absolute value. Distractors: 25/20 = 1.25 (ratio inverted); 0.20 (reports only the quantity change); 20/1 = 20.00 (divides unit changes instead of percentage changes)." },
  { id: "social-912-18", subject: "social-studies", band: "9-12", demand: "apply", strand: "economics", stem: "Using all of its resources, a country can produce either 40 tons of wheat or 10 tons of steel, and it can trade off between the two goods at a constant rate. What is the opportunity cost of producing 1 ton of steel?", options: ["0.25 tons of wheat", "30.00 tons of wheat", "4.00 tons of wheat", "40.00 tons of wheat"], key: "C", basis: "computed: opportunity cost of 1 ton of steel = wheat given up / steel gained = 40 / 10 = 4 tons of wheat. Distractors: 10/40 = 0.25 (ratio inverted, which is the cost of wheat in steel); 40 - 10 = 30 (subtracts instead of dividing); 40 (total wheat capacity rather than the per-ton cost)." },
  { id: "social-912-19", subject: "social-studies", band: "9-12", demand: "apply", strand: "economics", stem: "A severe frost destroys a large share of the orange crop just before harvest. Consumer demand for oranges does not change. In a competitive market, what will most likely happen to the equilibrium price and quantity of oranges?", options: ["Price falls and quantity falls", "Price rises and quantity rises", "Price rises and quantity falls", "Price falls and quantity rises"], key: "C", basis: "Law of supply and demand: a decrease in supply (leftward shift of the supply curve) with demand unchanged raises equilibrium price and lowers equilibrium quantity. The other options describe a demand decrease, a demand increase and a supply increase respectively." },
  { id: "social-912-20", subject: "social-studies", band: "9-12", demand: "recall", strand: "economics", stem: "A country's central bank wants to slow down rapidly rising prices. Which action would it most likely take?", options: ["Buy government bonds to expand the money supply", "Lower income tax rates for most households", "Sell government bonds to reduce the money supply", "Increase government spending on new highways"], key: "C", basis: "Contractionary monetary policy: open-market sales of government securities withdraw reserves from banks, reduce the money supply and raise interest rates, which lowers inflationary pressure. Buying bonds is expansionary, and tax and spending changes are fiscal policy set by the legislature, and both listed are expansionary." },
];

// ── The pilot ────────────────────────────────────────────────────────────────
// 12 items, one per cell. The only items that may reach the model before the freeze: they settle
// the format line and give the per-turn time. Never scored, never mixed into the 240.

export const K12_PILOT: K12Item[] = [
  { id: "pilot-01", subject: "math", band: "K-5", demand: "apply", strand: "whole-number arithmetic, place value", stem: "A box holds 48 crayons. How many crayons are in 6 boxes?", options: ["248", "54", "2,448", "288"], key: "D", basis: "computed: 6 x 48 = 6 x 40 + 6 x 8 = 240 + 48 = 288. 248 drops the carried 4 tens, 54 adds 48 + 6, 2,448 writes the partial products 24 and 48 side by side." },
  { id: "pilot-02", subject: "math", band: "6-8", demand: "apply", strand: "ratio, rate, percent", stem: "In a survey of 250 students, 36% said they walk to school. How many of the surveyed students do not walk to school?", options: ["90 students", "160 students", "214 students", "64 students"], key: "B", basis: "computed: 100% - 36% = 64%; 0.64 x 250 = 160 (check: 0.36 x 250 = 90 and 250 - 90 = 160). Distractors: 90 = the number who do walk; 214 = subtracted 36 from 250 as if it were a count; 64 = reported the percent that do not walk as a count." },
  { id: "pilot-03", subject: "math", band: "9-12", demand: "apply", strand: "linear, exponential, log functions", stem: "A plumber charges a flat fee of 40 dollars plus 32 dollars per hour of work. A customer's bill was 232 dollars. For how many hours did the plumber work?", options: ["6", "7", "8", "3"], key: "A", basis: "computed: 40 + 32h = 232, so 32h = 192 and h = 6. Distractors: 7 from 232/32 (ignoring the flat fee, about 7.25); 8 from adding the fee instead of subtracting ((232 + 40)/32 = 8.5); 3 from dividing 232 by 40 + 32 = 72." },
  { id: "pilot-04", subject: "science", band: "K-5", demand: "recall", strand: "matter, forces, energy", stem: "A guitar string is plucked and makes a sound. What causes the sound?", options: ["The string getting much hotter", "Light bouncing off the string", "The string vibrating back and forth", "The string becoming heavier"], key: "C", basis: "Sound is produced by vibrating objects; the vibrating string makes the surrounding air vibrate, and those vibrations travel to the ear." },
  { id: "pilot-05", subject: "science", band: "6-8", demand: "apply", strand: "motion, energy, waves", stem: "A box is sliding to the right across a floor. A student pushes it to the right with a force of 10 N while friction pushes on it to the left with a force of 10 N. No other horizontal forces act. What happens to the motion of the box?", options: ["It stops moving right away", "It keeps moving right at a constant speed", "It keeps moving right but slows down", "It keeps moving right and speeds up"], key: "B", basis: "Newton's first law: net force = 10 N - 10 N = 0 N, so the box's velocity does not change and it continues at constant speed. Stopping or slowing reflects the misconception that motion requires a net force." },
  { id: "pilot-06", subject: "science", band: "9-12", demand: "apply", strand: "biology", stem: "A red blood cell is placed in a salt solution that has a much higher solute concentration than the fluid inside the cell. The cell membrane lets water pass but not the salt. What happens to the cell?", options: ["It swells because water moves into the cell", "It bursts because salt moves into the cell", "It shrinks because water moves out of the cell", "It stays the same size because nothing crosses"], key: "C", basis: "Osmosis: water moves across a selectively permeable membrane toward the region of higher solute concentration, so a cell in a hypertonic solution loses water and shrinks." },
  { id: "pilot-07", subject: "ela", band: "K-5", demand: "recall", strand: "spelling, punctuation", stem: "Which choice is the correct contraction for the words do not?", options: ["do'nt", "don't", "dont'", "dont"], key: "B", basis: "In a contraction the apostrophe replaces the omitted letter(s); in 'do not' the o of 'not' is dropped, giving d-o-n-'-t. The distractors misplace or omit the apostrophe." },
  { id: "pilot-08", subject: "ela", band: "6-8", demand: "apply", strand: "figurative language, literary terms", stem: "Read the sentence: The morning sun reached through the curtains and tapped Ivy gently on the shoulder. Which type of figurative language does the writer use to describe the sun?", options: ["simile", "hyperbole", "personification", "alliteration"], key: "C", basis: "Personification gives human actions or qualities to a nonhuman thing; the sun is described as reaching and tapping someone on the shoulder. There is no 'like' or 'as' comparison, no exaggeration, and no repeated initial consonant sounds." },
  { id: "pilot-09", subject: "ela", band: "9-12", demand: "apply", strand: "usage and style", stem: "Which sentence uses apostrophes correctly?", options: ["The team lost it's lead when both coaches' plans fell apart.", "The team lost its lead when both coach's plans fell apart.", "The team lost its' lead when both coaches plans fell apart.", "The team lost its lead when both coaches' plans fell apart."], key: "D", basis: "Apostrophe rules: the possessive pronoun 'its' takes no apostrophe ('it's' means 'it is'; 'its'' is not a word), and the possessive of the plural noun 'coaches' is formed by adding an apostrophe after the s ('coaches'')." },
  { id: "pilot-10", subject: "social-studies", band: "K-5", demand: "recall", strand: "civics basics", stem: "What is the main job of the judicial branch of the United States government?", options: ["to write new laws", "to carry out the laws", "to lead the armed forces", "to decide what laws mean"], key: "D", basis: "US Constitution, Art. III: the judicial power, held by the courts, is to interpret laws and decide cases; writing laws is legislative and carrying them out and commanding the military are executive." },
  { id: "pilot-11", subject: "social-studies", band: "6-8", demand: "recall", strand: "world history to 1450", stem: "In medieval Europe, a lord grants a knight a piece of land. Under the feudal system, what is the knight expected to give the lord in return?", options: ["Loyalty and military service", "Several days of farm labor each week", "A share of votes in the royal council", "One-tenth of his harvest as a tithe"], key: "A", basis: "Feudalism: a vassal received a fief in exchange for an oath of loyalty and military service to the lord. Weekly farm labor was owed by serfs, and the tithe was paid to the Church." },
  { id: "pilot-12", subject: "social-studies", band: "9-12", demand: "recall", strand: "US history 1877-1991", stem: "In October 1962 the United States discovered that the Soviet Union was installing nuclear missiles in Cuba. Which action did President Kennedy announce as the first US response?", options: ["A naval quarantine to stop ships carrying weapons to the island", "A full-scale ground invasion to overthrow the Cuban government", "An airlift of food and fuel to supply people on the island", "A treaty giving up the US naval base on the island"], key: "A", basis: "During the Cuban Missile Crisis (October 1962) Kennedy announced a naval quarantine (blockade) of Cuba to halt further deliveries of offensive weapons; an invasion and air strikes were considered but not ordered, and the airlift distractor confuses the event with the Berlin Airlift of 1948-49." },
];
